css:
:root{
  --g900:#06382a; --g800:#0a4a35; --g700:#0d5c42; --g600:#11734f; --g500:#178a5f;
  --teal:#0f766e; --mint:#eef7f2; --mint2:#e3f1ea; --line:#d7e3dc; --line2:#e9f0ec;
  --ink:#1d2b26; --ink2:#4a5c55; --ink3:#7d8f88; --wht:#ffffff; --bg:#f4f7f5;
  --ok:#178a5f; --warn:#b7791f; --warnbg:#fdf6e7; --crit:#c0392b; --critbg:#fdeeec;
  --info:#1d6fa5; --infobg:#eaf3fa; --grey:#7d8f88; --greybg:#f0f3f1;
  --orng:#c2691a; --orngbg:#fdf1e6; --purp:#6b4ea8; --purpbg:#f2eefb; --okbg:#e6f4ed;
  --r:6px; --sh:0 1px 2px rgba(6,56,42,.06),0 2px 8px rgba(6,56,42,.05);
  --hair:#e7ede9; --gold:#c9a227; --gold2:#f2e0a6; --sub:#4f5b56;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{background:var(--bg);color:var(--ink);font:14.5px/1.45 "Segoe UI",Inter,-apple-system,Roboto,Arial,sans-serif;-webkit-font-smoothing:antialiased}
.wrap{max-width:100%;padding:0 14px 30px}

/* ── masthead ── */
.mast{background:linear-gradient(100deg,var(--g900),var(--g700) 58%,var(--teal));color:#fff;padding:10px 16px;display:flex;align-items:center;gap:14px;flex-wrap:wrap;box-shadow:0 2px 10px rgba(6,56,42,.18)}
.logo{width:34px;height:34px;border-radius:8px;background:linear-gradient(145deg,#2ec27e,#0d5c42);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:13px;letter-spacing:.5px;box-shadow:inset 0 1px 0 rgba(255,255,255,.35)}
.mast h1{font-size:16px;margin:0;font-weight:650;letter-spacing:.2px}
.mast .sub{font-size:11.5px;opacity:.82;margin-top:1px}
.mast .spacer{flex:1}
.mchip{background:rgba(255,255,255,.13);border:1px solid rgba(255,255,255,.22);padding:4px 9px;border-radius:20px;font-size:11.5px;display:flex;align-items:center;gap:6px}
.mbtn{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.25);color:#fff;padding:6px 11px;border-radius:5px;font-size:12.5px;cursor:pointer}
.mbtn:hover{background:rgba(255,255,255,.24)}

/* ── tabs ── */
.tabs{display:flex;align-items:center;gap:4px;border-bottom:1px solid var(--hair);margin:0 0 10px;padding:0 2px}
.tab{padding:7px 15px;font-size:13px;font-weight:650;color:var(--ink2);background:#eef3f0;border:1px solid transparent;border-bottom:0;border-radius:6px 6px 0 0;cursor:pointer;margin-bottom:-1px}
.tab:hover{color:var(--g700)}
.tab.on{background:#fff;color:var(--g900);border-color:var(--hair);border-top:2px solid var(--gold)}
.tabpane{display:none}.tabpane.show{display:block}
/* ── edge panel ── */
.etab{position:fixed;right:0;top:46%;background:var(--g700);color:#fff;padding:12px 6px;border-radius:6px 0 0 6px;cursor:pointer;z-index:45;box-shadow:-2px 2px 8px rgba(0,0,0,.18);font-size:15px}
.etab:hover{background:var(--g600)}
.epanel{position:fixed;top:0;right:0;bottom:0;width:360px;max-width:92vw;background:#fff;border-left:1px solid var(--hair);box-shadow:-8px 0 26px rgba(6,56,42,.16);transform:translateX(102%);transition:transform .22s;z-index:55;display:flex;flex-direction:column}
.epanel.on{transform:none}
.ehd{display:flex;align-items:center;gap:8px;padding:9px 12px;background:linear-gradient(100deg,var(--g900),var(--g700));color:#fff}
.ehd b{font-size:13.5px;flex:1}
.x2{background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.28);color:#fff;width:24px;height:24px;border-radius:5px;cursor:pointer;font-size:14px}
.ebar{display:flex;gap:6px;padding:8px 12px;border-bottom:1px solid var(--hair);background:var(--mint)}
.ebar select{flex:1;padding:5px 6px;border:1px solid var(--line);border-radius:4px;font-size:12.5px;font-family:inherit}
.ebody{flex:1;overflow:auto;padding:10px 12px}
.ecnt{background:linear-gradient(145deg,var(--g700),var(--teal));color:#fff;border-radius:6px;padding:10px 12px;margin-bottom:9px}
.ecnt .n{font-size:30px;font-weight:800;line-height:1}
.ecnt .l{font-size:11.5px;opacity:.9;margin-top:2px}
.ecnt .sp{display:flex;gap:12px;margin-top:6px;font-size:12px}
.egrp{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-bottom:10px}
.eg{border:1px solid var(--hair);border-radius:5px;padding:5px 8px;background:var(--mint)}
.eg .k{font-size:11px;color:var(--sub)} .eg .v{font-size:16px;font-weight:700;color:var(--g900)}
.elist{border:1px solid var(--hair);border-radius:5px;overflow:hidden}
.eli{display:flex;align-items:center;gap:8px;padding:6px 8px;border-bottom:1px solid var(--line2);cursor:pointer}
.eli:last-child{border-bottom:0}
.eli:nth-child(even){background:#f6faf8}
.eli:hover{background:var(--mint2)}
.eli .nm{flex:1;min-width:0}
.eli .n1{font-size:12.5px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.eli .n2{font-size:11px;color:var(--sub)}
.eli .dt{font-size:11px;color:var(--sub);white-space:nowrap}
.eh{font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:var(--ink3);margin:0 0 4px}
/* ── capacity planner ── */
.capgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:9px 11px;margin-bottom:4px}
.capcards{display:grid;grid-template-columns:repeat(auto-fit,minmax(168px,1fr));gap:9px;margin:12px 0}
.cc{border-radius:7px;padding:11px 13px;color:#fff;box-shadow:0 2px 8px rgba(6,56,42,.14)}
.cc .k{font-size:11.5px;opacity:.92}
.cc .v{font-size:31px;font-weight:800;line-height:1.05;margin:2px 0}
.cc .d{font-size:11.5px;opacity:.92}
.cc.g{background:linear-gradient(140deg,#0d5c42,#1ea36c)}
.cc.b{background:linear-gradient(140deg,#134e6f,#2a7fa8)}
.cc.a{background:linear-gradient(140deg,#8a5a08,#c8912a)}
.cc.r{background:linear-gradient(140deg,#8e2a20,#c0392b)}
.cc.p{background:linear-gradient(140deg,#4b2f7a,#7d57bd)}
.bneck{border-radius:6px;padding:9px 12px;font-size:13px;font-weight:650;margin-bottom:10px;border:1px solid}
.bneck.ok{background:var(--okbg);color:var(--ok);border-color:#bde3d0}
.bneck.wr{background:var(--warnbg);color:var(--warn);border-color:#f0dcae}
.bneck.cr{background:var(--critbg);color:var(--crit);border-color:#f2c4bd}
.bar{height:16px;border-radius:9px;background:#e9f0ec;overflow:hidden;margin-top:4px}
.bar i{display:block;height:100%;border-radius:9px}
/* ── collapsible info / analysis sections ── */
.xsec{position:relative;background:#fff;border:1px solid var(--hair);border-radius:var(--r);margin-bottom:9px;box-shadow:0 1px 2px rgba(6,56,42,.05);overflow:hidden}
.xbar{display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding:6px 12px;background:linear-gradient(180deg,#fff,#f9fcfa);border-bottom:1px solid transparent;cursor:pointer;position:relative}
.xsec.open .xbar{border-bottom-color:var(--hair)}
.xbar:after{content:"";position:absolute;left:8px;right:8px;bottom:-1px;height:1px;background:linear-gradient(90deg,rgba(201,162,39,0),rgba(201,162,39,.45),rgba(201,162,39,0));opacity:0}
.xsec.open .xbar:after{opacity:1}
.xbar b{font-size:13px;color:var(--g900)}
.caret2{color:var(--g700);font-size:11px;cursor:pointer;display:inline-block}
.xbody{display:none;padding:11px 12px}
.xsec.open .xbody{display:block}
.about{display:grid;grid-template-columns:repeat(auto-fit,minmax(255px,1fr));gap:10px}
.about h5{margin:0 0 4px;font-size:12px;color:var(--g800)}
.about p{margin:0 0 6px;font-size:12px;color:var(--sub);line-height:1.5}
.about ul{margin:0;padding-left:15px;font-size:12px;color:var(--sub);line-height:1.6}
.about li b{color:var(--ink)}
.rpt{border:1px solid var(--hair);border-radius:5px;margin-bottom:9px;overflow:hidden;background:#fff}
.rhd{display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding:5px 10px;background:linear-gradient(180deg,var(--mint),var(--mint2));border-bottom:1px solid var(--hair);cursor:pointer}
.rhd b{font-size:12.5px;color:var(--g900)}
.rbody{padding:8px 10px;overflow:auto}
.rpt.shut .rbody{display:none}
.rpt.shut .rhd{border-bottom:0}
.repnote{font-size:11.5px;color:var(--sub);margin:0 0 8px}
table.anz{border-collapse:collapse;width:100%;font-size:13px;margin-top:4px}
table.anz th,table.anz td{border:1px solid var(--hair);padding:5px 8px;text-align:right;white-space:nowrap}
table.anz td{font-weight:650;color:var(--ink)}
table.anz th{background:var(--mint);color:var(--g900);font-weight:700;font-size:12px;position:sticky;top:0}
table.anz td.gd{color:#0f7a52;background:#eaf7f0}
table.anz td.bd{color:#c0392b;background:#fdefec}
table.anz td.zz{color:var(--ink3);font-weight:400}
table.anz td:first-child,table.anz th:first-child{text-align:left;font-weight:600}
table.anz tr:nth-child(even) td{background:#f4f9f6}
table.anz tr.tot td{background:var(--mint2);font-weight:700;color:var(--g900)}
table.anz tr.sp td{background:var(--g700);color:#fff;font-weight:700;letter-spacing:.4px}
table.anz .f{color:#b0246b} table.anz .m{color:#17559c}
.anwrap{overflow:auto}
.angrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:12px}
/* ── sleek head bar ── */
.headbar{position:relative;display:flex;align-items:center;gap:12px;flex-wrap:wrap;
 background:linear-gradient(180deg,#ffffff,#fafdfb);border:1px solid var(--hair);
 border-radius:var(--r);padding:6px 12px;margin:12px 0 9px;box-shadow:0 1px 2px rgba(6,56,42,.05)}
.headbar:before,.headbar:after{content:"";position:absolute;left:8px;right:8px;height:1px;
 background:linear-gradient(90deg,rgba(201,162,39,0),var(--gold) 18%,var(--gold2) 50%,var(--gold) 82%,rgba(201,162,39,0))}
.headbar:before{top:-1px}.headbar:after{bottom:-1px}
.hb-ic{width:26px;height:26px;border-radius:6px;flex:0 0 auto;display:flex;align-items:center;justify-content:center;
 background:linear-gradient(145deg,var(--g700),var(--teal));color:#fff;font-size:13px;
 box-shadow:0 0 0 1px rgba(201,162,39,.45)}
.headbar h2{margin:0;font-size:16.5px;font-weight:670;color:var(--g900);letter-spacing:-.15px;line-height:1.15}
.hb-s{font-size:11.5px;color:var(--sub)}
.hb-div{width:1px;height:22px;background:linear-gradient(180deg,transparent,var(--gold2),transparent)}
.pact{margin-left:auto;display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.btn{border:1px solid var(--line);background:#fff;color:var(--ink);padding:6px 11px;border-radius:5px;font-size:12.5px;cursor:pointer;display:inline-flex;align-items:center;gap:6px}
.btn:hover{border-color:var(--g500);color:var(--g700)}
.btn.pri{background:var(--g700);border-color:var(--g700);color:#fff}
.btn.pri:hover{background:var(--g600)}
.btn.sm{padding:4px 8px;font-size:12px}

/* ── kpi ── */

/* ── filter panel ── */
.fpanel{background:#fff;border:1px solid var(--hair);border-radius:var(--r);box-shadow:var(--sh);margin-bottom:11px;overflow:hidden}
.fbar{display:flex;align-items:center;gap:10px;padding:7px 12px;background:linear-gradient(180deg,var(--mint),var(--mint2));border-bottom:1px solid var(--hair);cursor:pointer;flex-wrap:wrap;position:relative}
.fbar:after{content:"";position:absolute;left:8px;right:8px;bottom:-1px;height:1px;background:linear-gradient(90deg,rgba(201,162,39,0),rgba(201,162,39,.55),rgba(201,162,39,0))}
.fbar h3{margin:0;font-size:13.5px;color:var(--g900);font-weight:650;display:flex;align-items:center;gap:7px}
.caret{transition:transform .18s;font-size:11px;color:var(--g700)}
.fpanel.open .caret{transform:rotate(90deg)}
.fbody{display:none;padding:10px 12px 11px}
.fpanel.open .fbody{display:block}
.fgrid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:9px 14px;align-items:end;width:100%}
.fld{min-width:0;margin:0}
.fld label{display:block;font-size:11px;line-height:1.2;color:var(--ink3);margin:0 0 3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fld select,.fld input{width:100%;min-width:0;height:38px;box-sizing:border-box;padding:5px 8px;border:1px solid var(--line);border-radius:5px;font-size:12.5px;color:var(--ink);background:#fff;font-family:inherit;margin:0}
.fld select:focus,.fld input:focus{outline:2px solid rgba(17,115,79,.25);border-color:var(--g500)}
.fsep{grid-column:1/-1;height:1px;background:var(--line2);margin:1px 0 0}
.fact{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-top:11px;padding-top:10px;border-top:1px solid var(--line2)}
.chips{display:flex;gap:6px;flex-wrap:wrap;padding:6px 12px;border-bottom:1px solid var(--hair);background:#fbfdfc}
.chip{border:1px solid var(--line);background:#fff;border-radius:16px;padding:3px 10px;font-size:11.5px;color:var(--ink2);cursor:pointer;white-space:nowrap}
.chip:hover{border-color:var(--g500);color:var(--g700)}
.chip.on{background:var(--g700);border-color:var(--g700);color:#fff}

/* ── toolbar ── */
.tbar{display:flex;align-items:center;gap:9px;flex-wrap:wrap;background:#fff;border:1px solid var(--hair);border-bottom:0;border-radius:var(--r) var(--r) 0 0;padding:7px 11px;position:relative}
.tbar:before{content:"";position:absolute;left:8px;right:8px;top:-1px;height:1px;background:linear-gradient(90deg,rgba(201,162,39,0),rgba(201,162,39,.45),rgba(201,162,39,0))}
.srch{position:relative;flex:0 1 330px;min-width:210px}
.srch input{width:100%;padding:6px 28px 6px 28px;border:1px solid var(--line);border-radius:20px;font-size:12.5px;font-family:inherit}
.srch input:focus{outline:2px solid rgba(17,115,79,.25);border-color:var(--g500)}
.srch .si{position:absolute;left:9px;top:50%;transform:translateY(-50%);color:var(--ink3);font-size:12px}
.srch .sx{position:absolute;right:7px;top:50%;transform:translateY(-50%);color:var(--ink3);cursor:pointer;font-size:14px;display:none}
.cnt{font-size:12px;color:var(--ink2)}
.cnt b{color:var(--g900)}
.tsp{flex:1}

/* ── table ── */
.tscroll{background:#fff;border:1px solid var(--hair);border-radius:0 0 var(--r) var(--r);overflow:auto;max-height:calc(100vh - 150px)}
table.reg{border-collapse:separate;border-spacing:0;width:100%;font-size:12.5px;table-layout:auto}
table.reg thead th{position:sticky;top:0;z-index:5;background:linear-gradient(180deg,var(--g800),var(--g700));color:#fff;font-weight:600;font-size:11.5px;text-align:left;padding:6px 6px;border-right:1px solid rgba(255,255,255,.12);border-bottom:2px solid var(--g900);white-space:nowrap;cursor:pointer;user-select:none}
table.reg thead th .h2l{display:block;font-size:10px;font-weight:400;opacity:.72;letter-spacing:.1px}
table.reg thead th:hover{background:var(--g600)}
table.reg thead th.nos{cursor:default}
table.reg tbody td{padding:6px 6px;border-bottom:1px solid #e8efeb;border-right:1px solid #eef4f1;vertical-align:middle;max-width:150px}
table.reg tbody tr{cursor:pointer}
table.reg tbody tr:nth-child(even){background:#eaf2ed}
table.reg tbody tr:hover{background:#dfeee6}
table.reg tbody tr.zs{box-shadow:inset 3px 0 0 var(--crit)}
.c1{font-weight:600;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.c2{font-size:11px;color:var(--sub);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.c2.g{color:var(--ok)} .c2.r{color:var(--crit)} .c2.a{color:var(--warn)} .c2.b{color:var(--info)}
.dl .dk{color:var(--sub)}
.num{text-align:right}
.sn{color:var(--ink3);font-size:11.5px;text-align:right}
.bdg{display:inline-block;padding:1px 6px;border-radius:10px;font-size:10.5px;font-weight:600;white-space:nowrap;line-height:1.5}
.b-ok{background:var(--okbg);color:var(--ok)} .b-wa{background:var(--warnbg);color:var(--warn)}
.b-cr{background:var(--critbg);color:var(--crit)} .b-in{background:var(--infobg);color:var(--info)}
.b-gr{background:var(--greybg);color:var(--grey)} .b-or{background:var(--orngbg);color:var(--orng)}
.b-pu{background:var(--purpbg);color:var(--purp)}
.eye{border:1px solid var(--line);background:#fff;border-radius:4px;width:24px;height:22px;display:flex;align-items:center;justify-content:center;cursor:pointer;color:var(--g700);margin:0 auto}
.eye:hover{background:var(--g700);color:#fff;border-color:var(--g700)}
.don{display:flex;align-items:center;gap:5px}
.don svg{flex:0 0 auto}
.don span{font-size:11px;font-weight:600;color:var(--ink2)}
.empty{padding:40px 16px;text-align:center;color:var(--ink3)}
.empty .e1{font-size:15px;color:var(--ink2);margin-bottom:4px;font-weight:600}

/* ── pager ── */
.pager{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:8px 11px;background:#fff;border:1px solid var(--hair);border-top:0;border-radius:0 0 var(--r) var(--r);margin-bottom:14px}
.pg{border:1px solid var(--line);background:#fff;min-width:27px;height:26px;padding:0 7px;border-radius:4px;font-size:12px;cursor:pointer;color:var(--ink2)}
.pg:hover:not(:disabled){border-color:var(--g500);color:var(--g700)}
.pg.on{background:var(--g700);border-color:var(--g700);color:#fff;font-weight:600}
.pg:disabled{opacity:.4;cursor:not-allowed}
.pgd{color:var(--ink3);padding:0 2px}
.psel{padding:4px 6px;border:1px solid var(--line);border-radius:4px;font-size:12px;font-family:inherit}

/* ── modal ── */
.ov{position:fixed;inset:0;background:rgba(6,56,42,.45);display:none;align-items:flex-start;justify-content:center;z-index:60;padding:22px 14px;overflow:auto}
.ov.on{display:flex}
.mod{background:#fff;border-radius:9px;width:min(1020px,100%);box-shadow:0 20px 60px rgba(0,0,0,.3);overflow:hidden}
.mhd{background:linear-gradient(100deg,var(--g900),var(--g700));color:#fff;padding:12px 16px;display:flex;align-items:center;gap:12px}
.mhd .av{width:40px;height:40px;border-radius:9px;background:rgba(255,255,255,.16);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:15px}
.mhd h3{margin:0;font-size:16px;font-weight:650}
.mhd .ms{font-size:11.5px;opacity:.85;margin-top:2px}
.x{margin-left:auto;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.25);color:#fff;width:28px;height:28px;border-radius:5px;cursor:pointer;font-size:15px}
.mbd{padding:14px 16px;max-height:70vh;overflow:auto}
.sec{margin-bottom:13px}
.sec h4{margin:0 0 7px;font-size:12.5px;color:var(--g800);font-weight:650;padding-bottom:5px;border-bottom:1px solid var(--line2);display:flex;align-items:center;gap:6px}
.dgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px}
.dl{background:var(--mint);border:1px solid var(--line2);border-radius:5px;padding:6px 9px;min-width:0}
.dl .dk{font-size:10.5px;color:var(--ink3)}
.dl .dv{font-size:13px;font-weight:600;color:var(--ink);margin-top:1px;word-break:break-word}
.tline{border-left:2px solid var(--line);padding-left:11px;margin-left:5px}
.tl{position:relative;padding:0 0 9px 0;font-size:12px;color:var(--ink2)}
.tl:before{content:"";position:absolute;left:-16px;top:5px;width:7px;height:7px;border-radius:50%;background:var(--g500);border:2px solid #fff}
.tl b{color:var(--ink)}
.mft{padding:10px 16px;border-top:1px solid var(--line);background:#fbfdfc;display:flex;gap:7px;justify-content:flex-end}
.ltoast{position:fixed;bottom:18px;right:18px;background:var(--g800);color:#fff;padding:9px 14px;border-radius:6px;font-size:12.5px;box-shadow:0 8px 24px rgba(0,0,0,.25);opacity:0;transform:translateY(8px);transition:.22s;z-index:90}
.ltoast.on{opacity:1;transform:none}
.hint{font-size:11.5px;color:var(--ink3)}
kbd{background:#fff;border:1px solid var(--line);border-bottom-width:2px;border-radius:3px;padding:0 4px;font-size:10.5px;font-family:inherit;color:var(--ink2)}

/* ── compact client 360 ── */
.mod{width:min(1140px,100%)}
.mhd{padding:9px 14px}
.mhd .abtn.big{flex:0 0 auto}
.mhd .av{width:34px;height:34px;border-radius:8px;font-size:13px}
