/* scroll arrows + drag */
.tzone{position:relative}
.sarrow{position:absolute;top:0;bottom:0;width:58px;display:flex;align-items:center;justify-content:center;font-size:34px;color:#fff;opacity:0;transition:opacity .2s;pointer-events:none;z-index:9;text-shadow:0 2px 8px rgba(0,0,0,.4);font-weight:300}
.sarrow.l{left:0;background:linear-gradient(90deg,rgba(6,56,42,.40),rgba(6,56,42,0))}
.sarrow.r{right:0;background:linear-gradient(270deg,rgba(6,56,42,.40),rgba(6,56,42,0))}
.tzone.hint-l .sarrow.l,.tzone.hint-r .sarrow.r{opacity:.35;pointer-events:auto;cursor:pointer}
.tzone.hint-l.act-l .sarrow.l,.tzone.hint-r.act-r .sarrow.r{opacity:.9}
.hidnote{position:absolute;bottom:8px;left:50%;transform:translateX(-50%);background:rgba(6,56,42,.82);color:#fff;font-size:11px;padding:3px 11px;border-radius:14px;z-index:9;opacity:0;transition:.2s;pointer-events:none}
.tzone.hint-r .hidnote,.tzone.hint-l .hidnote{opacity:.9}
