.act.mail{background:var(--purpbg);color:var(--purp)}
.act:hover{filter:brightness(.94)}
.act.off{background:var(--greybg);color:var(--grey);opacity:.45;pointer-events:none}
.pcol{cursor:pointer;display:block;background:var(--mint);border:1px solid var(--line2);border-radius:5px;padding:5px 8px}
.pcol input{margin-right:5px}
.pcol.sel{background:var(--okbg);border-color:var(--g500)}
@media (max-width:900px){.tscroll{max-height:none}.phead h2{font-size:19px}}
.printhead{display:none}
@page{size:A4 landscape;margin:7mm}
@media print{
 .mast,.fpanel,.tbar,.pager,.pact,.chips,.sarrow,.hidnote,.ov,.ltoast,.headbar, .printhead{display:block!important;margin:0 0 7px;padding:0 0 5px;border-bottom:1.5px solid #c9a227}
