/* ═══════════ ADVANCED FINANCIAL PANEL (client 360) ═══════════ */
.finw{border:1px solid var(--hair);border-radius:7px;background:linear-gradient(180deg,#fbfdfc,#fff);padding:9px 11px 10px;margin-bottom:10px;box-shadow:0 1px 3px rgba(6,56,42,.06)}
