.fpill.wa{background:var(--warnbg);color:var(--warn);border-color:#f0dcae}
.fpill.cr{background:var(--critbg);color:var(--crit);border-color:#f2c4bd}
.ftiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(132px,1fr));gap:7px;margin-bottom:9px}
.ftile{border-radius:7px;padding:7px 10px;color:#fff;box-shadow:0 2px 7px rgba(6,56,42,.13);min-width:0}
.ftile .k{font-size:10px;opacity:.9;letter-spacing:.3px;text-transform:uppercase}
