.ftile.t{background:linear-gradient(140deg,#0f5d5a,#189a8e)}
.ftile.b{background:linear-gradient(140deg,#15496a,#2a7fa8)}
.ftile.a{background:linear-gradient(140deg,#8a5a08,#c8912a)}
.ftile.r{background:linear-gradient(140deg,#8e2a20,#c0392b)}
.ftile.p{background:linear-gradient(140deg,#4b2f7a,#7d57bd)}
.fsplit{display:grid;grid-template-columns:minmax(260px,1fr) minmax(300px,1.35fr);gap:9px;margin-bottom:9px;align-items:start}
.fbox{border:1px solid var(--hair);border-radius:6px;background:#fff;padding:8px 10px}
.frow{margin-bottom:8px}.frow:last-child{margin-bottom:0}
.frow .fl{display:flex;align-items:baseline;gap:6px;font-size:11px;color:var(--sub);margin-bottom:3px}
.frow .fl b{font-size:12px;color:var(--ink)}
