.fb i.p1{background:linear-gradient(90deg,#178a5f,#2ec27e)}
.fb i.p2{background:linear-gradient(90deg,#1d6fa5,#3f9fd6)}
.fb i.p3{background:repeating-linear-gradient(45deg,#f0dcae,#f0dcae 5px,#f7e9c6 5px,#f7e9c6 10px)}
.falert{border-radius:5px;padding:6px 9px;font-size:11.5px;font-weight:600;border:1px solid;margin-top:8px;line-height:1.45}
.falert.cr{background:var(--critbg);color:var(--crit);border-color:#f2c4bd}
.falert.ok{background:var(--okbg);color:var(--ok);border-color:#bde3d0}
.falert.in{background:var(--infobg);color:var(--info);border-color:#cbe1f1}
.ftwo{display:grid;grid-template-columns:minmax(340px,1.6fr) minmax(250px,1fr);gap:9px}
.fttl{font-size:10.5px;text-transform:uppercase;letter-spacing:.4px;color:var(--ink3);margin:0 0 4px}
.fhd{display:flex;align-items:baseline;gap:9px;margin:13px 0 6px;padding:5px 10px;border-radius:7px;
 background:linear-gradient(90deg,var(--mint),rgba(238,247,242,0));border-left:3px solid var(--g600)}
.fhd b{font-size:12.5px;font-weight:700;color:var(--g900);letter-spacing:.2px}
.fhd span{font-size:11.5px;color:var(--sub)}
.fhd i{margin-left:auto;font-style:normal;font-size:11.5px;font-weight:700;color:var(--g700)}
/* wire-line activity */
.wline{position:relative;margin:4px 0 0 8px;padding-left:20px;border-left:2px solid var(--line)}
.wli{position:relative;padding:0 0 13px}
.wli:last-child{padding-bottom:2px}
.wli:before{content:"";position:absolute;left:-26px;top:3px;width:11px;height:11px;border-radius:50%;
 background:#fff;border:2.5px solid var(--g600);box-shadow:0 0 0 3px #fff}
.wli.a:before{border-color:var(--warn)} .wli.r:before{border-color:var(--crit)}
.wli b{font-size:12.5px;font-weight:700;color:var(--g900);margin-right:8px}
.wli span{font-size:12.5px;color:var(--sub)}
table.ftab{border-collapse:collapse;width:100%;font-size:12px;background:#fff}
table.ftab th{background:linear-gradient(180deg,var(--mint),var(--mint2));color:var(--g900);font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:.3px;padding:6px 8px;border:1px solid var(--hair);text-align:right;white-space:nowrap}
table.ftab td{padding:6px 8px;line-height:1.5;border:1px solid var(--line2);text-align:right;white-space:nowrap}
