table.ftab tr:nth-child(even) td{background:#f7faf8}
table.ftab tr.tot td{background:var(--mint2);font-weight:750;color:var(--g900);border-top:1.5px solid var(--g600)}
table.ftab td.g{color:#0f7a52;font-weight:700} table.ftab td.r{color:#c0392b;font-weight:700}
table.ftab td.a{color:var(--warn);font-weight:700}
.mtag{display:inline-block;font-size:9.5px;font-weight:750;padding:1px 6px;border-radius:9px;border:1px solid;white-space:nowrap}
.m-sl{background:#eaf7f0;color:#0f7a52;border-color:#bde3d0} .m-sk{background:#eaf3fa;color:#1d6fa5;border-color:#cbe1f1}
.m-ha{background:#f2eefb;color:#6b4ea8;border-color:#ded2f4} .m-ae{background:#fdeef5;color:#b0246b;border-color:#f4cfe0}
.m-ht{background:#fdf1e6;color:#c2691a;border-color:#f3d9be} .m-ns{background:#fdf6e7;color:#b7791f;border-color:#f0dcae}
.m-gl{background:#e7f6f4;color:#0f766e;border-color:#c2e5e1} .m-lr{background:#eef7f2;color:#11734f;border-color:#cfe6da}
.m-ph{background:#f0f3f1;color:#4a5c55;border-color:#dbe3de} .m-dg{background:#eef3fa;color:#3d5a80;border-color:#d3e0ee}
.m-ad{background:#f0f3f1;color:#7d8f88;border-color:#dbe3de}
.ubar{display:inline-block;width:46px;height:7px;border-radius:5px;background:#e9f0ec;overflow:hidden;vertical-align:middle;margin-left:5px}
.ubar i{display:block;height:100%;background:linear-gradient(90deg,#178a5f,#2ec27e)}
.fmini{align-content:start}
.fsc{overflow:auto;max-width:100%;border-radius:5px}
.fsc table.ftab{min-width:100%}
@media(max-width:900px){.fsplit,.ftwo{grid-template-columns:1fr}}

/* ═══════════ ACTION LAUNCHER ═══════════ */
.abtn{display:inline-flex;align-items:center;gap:5px;font-family:inherit;font-size:11.5px;font-weight:700;color:var(--g900);
 background:linear-gradient(180deg,#fff,#f3f8f5);border:1px solid var(--line);border-left:3px solid var(--gold);
 border-radius:5px;padding:3px 9px;cursor:pointer;white-space:nowrap;box-shadow:0 1px 2px rgba(6,56,42,.07)}
.abtn:hover{background:linear-gradient(180deg,var(--mint),var(--mint2));border-color:var(--g500);border-left-color:var(--gold)}
