.amenu{position:fixed;z-index:90;width:360px;max-width:94vw;background:#fff;border:1px solid var(--hair);border-radius:16px;
 box-shadow:0 22px 60px rgba(6,56,42,.32);overflow:hidden;display:none;display:none}
