/* LIFE ERP · Enrollment Register · Live v11.1 FAST CLIENT ACTIONS — paste into Web Page › Scripting › Javascript */
(function(){
"use strict_off";
function START(){
if(window.__lifeEnrollmentRegister)return;
if(!document.getElementById("lifeER")){setTimeout(START,200);return}
window.__lifeEnrollmentRegister=true;

/* ═════════════════════════════════════════════════════════════════════
   LIFE ERP — ENROLLMENT REGISTER · LIVE v11
   Screen = v10 format (unchanged). Data = live LIFE ERP (portal.lifescc.com)
   One row = one enrollment = one Therapy Plan.
   Sources: Therapy Plan (+ Therapy Plan Detail), Sales Invoice, Payment Entry,
            Therapy Session (sessions, weight & inch), Patient, Patient Appointment,
