            Healthcare Practitioner, Employee (Center Manager).
   ═════════════════════════════════════════════════════════════════════ */

/* ═══════════ CONFIG — edit values here, not code ═══════════ */
const CFG={
 EXCLUDED:["Testing Branch","Head Office","Ho CC"],
 /* branch name in ERP : [short code, cluster] */
 BRANCH:{
  "Madhapur":["MP","Cluster 1"],"Chandanagar":["CN","Cluster 1"],"Gachibowli":["GB","Cluster 1"],"Kukatpally":["KP","Cluster 1"],
  "Banjara Hills":["BH","Cluster 2"],"SR Nagar":["SN","Cluster 2"],"Dilsukhnagar":["DN","Cluster 2"],"Himayathnagar":["HN","Cluster 2"],
  "Vijayawada":["VW","Cluster 3"],"Vizag":["VZ","Cluster 3"],"Nellore":["NLR","Cluster 3"]},
 CLHEAD:{"Cluster 1":"Teena","Cluster 2":"Bindu","Cluster 3":"Preethi","Other":"—"},
 MANAGER_DESIGNATIONS:["Center Manager","Centre Manager","Branch Manager"],
 NJ_DAYS:30,          /* NJ badge: New Joining enrolled within these many days */
 BREAK_DAYS:45,       /* no session for these many days → Break */
 REGULAR_AMV:1.2,     /* visits per month for Regular */
 CHUNK:120,           /* ids per API request */
 PAGE:2000,           /* rows per API page */
 PARALLEL:4,          /* parallel requests */
 LINKS:{plan:"/app/therapy-plan/",patient:"/app/patient/",inv:"/app/sales-invoice/",pe:"/app/payment-entry/",
  weight:"/client-weight-loss-info",result:"/slimming-&-demart-report"}
};

/* ═══════════ DATES ═══════════ */
function d2s(d){return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}
const TODAY=d2s(new Date());
const MSTART=TODAY.slice(0,8)+"01";
function fdt(x){if(!x)return"—";const p=String(x).slice(0,10).split("-");if(p.length<3)return String(x);return p[2]+" "+["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][+p[1]-1]+" "+p[0].slice(2)}
function inr(n){return "₹"+Math.round(Number(n)||0).toLocaleString("en-IN")}
function dayDiff(a,b){if(!a||!b)return null;return Math.round((new Date(String(b).slice(0,10))-new Date(String(a).slice(0,10)))/864e5)}
function addM(iso,m){const d=new Date(iso+"T00:00:00");d.setMonth(d.getMonth()+m);return d2s(d)}
const N=v=>Number(v)||0;
const cln=s=>String(s==null?"":s).replace(/[<>"`\\]/g,"").replace(/\s+/g," ").trim();
const iso10=s=>s?String(s).slice(0,10):"";
const dig=s=>{const x=String(s||"").replace(/\D/g,"");return x.length>10?x.slice(-10):x};

/* ═══════════ MASTERS (built from live data after load) ═══════════ */
let BR=Object.keys(CFG.BRANCH).map(n=>({c:CFG.BRANCH[n][0],n:n,cl:CFG.BRANCH[n][1],bm:"—"}));
const CLHEAD=CFG.CLHEAD;
const CAT=["New Joining","Rebooking","Renewal","Upgrade","Cross Sell (C2C)","Referral Join","Branch Transfer","Corporate / B2B"];
const MAIN=["Slimming","Skin (Dermatology)","Hair Treatment","Aesthetics","Hair Transplant (HT)","Hair Restro (NSHR)","GLP","LIFE RISE","Physiotherapy & PM","Diagnostics & Assessments","Administrative Services"];
const MSH={"Slimming":"Slimming","Skin (Dermatology)":"Skin","Hair Treatment":"Hair","Aesthetics":"Aesthetics","Hair Transplant (HT)":"HT","Hair Restro (NSHR)":"NSHR","GLP":"GLP-1","LIFE RISE":"LIFE RISE","Physiotherapy & PM":"Physio","Diagnostics & Assessments":"Diagnostics","Administrative Services":"Admin"};
const MCL={"Slimming":"m-sl","Skin (Dermatology)":"m-sk","Hair Treatment":"m-ha","Aesthetics":"m-ae","Hair Transplant (HT)":"m-ht","Hair Restro (NSHR)":"m-ns","GLP":"m-gl","LIFE RISE":"m-lr","Physiotherapy & PM":"m-ph","Diagnostics & Assessments":"m-dg","Administrative Services":"m-ad"};
const VERT=MAIN;
let GRP=[],ITEMS=[],PARTS=[];
const MED=["Fit","PCOD","Thyroid","Diabetic","Hypertension","Anaemia","Heart condition","Post Surgery","Under Review","Not recorded"];
const CT=["Call","Message","Mail","DND"];
let CONS=[],CC=[],STAFF=[];
const DATA=[];
const LIVE={busy:false,loaded:false,mastersOK:false,from:"",to:"",tt:{},prac:{},bm:{},warn:[],user:"",at:""};

/* main category from therapy type master / name / service unit */
function mainNorm(v){
 const s=String(v||"").toLowerCase();
 if(!s)return "";
 if(/glp|mounjaro|tirzepat|semaglut|wegovy|ozempic/.test(s))return "GLP";
 if(/life ?rise|liferise/.test(s))return "LIFE RISE";
 if(/transplant|\bfue\b|graft|\bht\b/.test(s))return "Hair Transplant (HT)";
 if(/nshr|restro|hair patch|hair system|hair replacement|refix/.test(s))return "Hair Restro (NSHR)";
 if(/aesth|botox|filler|thread|profhilo|booster|skinvive|\bpmu\b|micropig|permanent makeup/.test(s))return "Aesthetics";
 if(/physio|pain/.test(s))return "Physiotherapy & PM";
 if(/diagnos|consult|\bbca\b|body composition|inbody|assessment/.test(s))return "Diagnostics & Assessments";
 if(/admin|erp charge|package charge|revalidation|conversion/.test(s))return "Administrative Services";
 if(/slim|weight|inch|cavitation|nsls|cryo|lipo|contour|tuck|wrap|ems\b|wms|body/.test(s))return "Slimming";
 if(/hair|scalp|gfc|prp.*hair|hft|dandruff|qr678/.test(s))return "Hair Treatment";
 if(/skin|derm|darmat|laser|lhr|peel|facial|pigment|acne|mnrf|wart|tag|glow|q.?switch|tattoo|hifu|carbon|toning|melas/.test(s))return "Skin (Dermatology)";
 return "";
}
function mainOfType(t,planCat){
 const T=LIVE.tt[t]||{};
 return mainNorm(T.custom_main_category)||mainNorm(t)||mainNorm(T.healthcare_service_unit)||mainNorm(planCat)||"Administrative Services";
}
function catClean(c){return cln(String(c||"").replace(/\s*-\s*LSACPL/i,""))}

/* ═══════════ API — same-origin Frappe calls under the logged-in user ═══════════ */
function csrf(){return (window.frappe&&frappe.csrf_token)||window.csrf_token||""}
async function api(method,args){
 const ctrl=(typeof AbortController!=="undefined")?new AbortController():null;
 const timer=setTimeout(()=>{try{if(ctrl)ctrl.abort()}catch(e){}},20000);
 try{
  const res=await fetch("/api/method/"+method,{
   method:"POST",
   credentials:"same-origin",
   headers:{
    "Content-Type":"application/json",
    "Accept":"application/json",
    "X-Frappe-CSRF-Token":csrf()
   },
   body:JSON.stringify(args||{}),
   signal:ctrl?ctrl.signal:undefined
  });
  let d={};
  let raw="";
  try{
   raw=await res.text();
   d=raw?JSON.parse(raw):{};
  }catch(e){
   d={};
  }
  if(!res.ok||d.exc||d.exc_type){
   let m=d.exception||d.exc_type||"";
   try{
    if(d._server_messages){
     m=JSON.parse(JSON.parse(d._server_messages)[0]).message||m;
    }
   }catch(e){}
   const er=new Error(
    String(m||("Request failed ("+res.status+")"))
     .replace(/<[^>]+>/g,"")
     .slice(0,400)
   );
   er.status=res.status;
   er.raw=(raw||JSON.stringify(d)).slice(0,3000);
   throw er;
  }
  return d.message;
 }catch(e){
  if(e&&e.name==="AbortError"){
   throw new Error("Request timed out: "+method);
  }
  throw e;
 }finally{
  clearTimeout(timer);
 }
}
function badField(e){
 const t=(e&&e.raw||"")+" "+(e&&e.message||"");
 const m=t.match(/Unknown column '(?:[`\w\s]+\.)?`?(\w+)`?'/i)||t.match(/Field not permitted in query:?\s*`?(\w+)/i)||t.match(/Invalid field:?\s*`?(\w+)/i)||t.match(/[Cc]annot (?:use|select) `?(\w+)/);
 return m?m[1]:null;
}
async function gl(dt,filters,fields,o){
 o=o||{};let f=fields.slice();
 for(let tries=0;tries<18;tries++){
  try{
   const out=[];let start=0;const lim=o.limit||500000;
   for(;;){
    const len=Math.min(o.page||CFG.PAGE,lim-out.length);
    const a={doctype:dt,filters:filters||[],fields:f,limit_start:start,limit_page_length:len,order_by:o.order||"name asc"};
    if(o.parent)a.parent=o.parent;
    if(o.group)a.group_by=o.group;
    const rows=await api("frappe.client.get_list",a)||[];
    out.push(...rows);
    if(rows.length<len||out.length>=lim)break;
    start+=rows.length;
   }
   return out;
  }catch(e){
   const b=badField(e);
   if(b&&f.length>1){
    const k=f.findIndex(x=>x===b||x.split(" as ")[0].replace(/.*\(|\).*/g,"").trim()===b||x.endsWith("."+b));
    if(k>-1){f.splice(k,1);warn(dt+" · field '"+b+"' not readable — shown as blank");continue}
   }
   throw e;
  }
 }
 return [];
}
async function glIn(dt,key,ids,extra,fields,o){
 const u=[...new Set((ids||[]).filter(Boolean))],parts=[];
 for(let i=0;i<u.length;i+=CFG.CHUNK)parts.push(u.slice(i,i+CFG.CHUNK));
 const out=[];let k=0;
 async function worker(){while(k<parts.length){const p=parts[k++];out.push(...await gl(dt,[[key,"in",p]].concat(extra||[]),fields,o))}}
 await Promise.all(Array.from({length:Math.min(CFG.PARALLEL,parts.length||1)},worker));
 return out;
}
function warn(m){if(!LIVE.warn.includes(m))LIVE.warn.push(m)}
