/* ═══════════ LOAD ONE DATA PERIOD ═══════════ */
async function loadLive(){
 if(LIVE.busy)return;
 const from=document.getElementById("d_from").value, to=document.getElementById("d_to").value;
 if(from&&to&&from>to){toast("From date must be before To date");return}
 LIVE.busy=true;LIVE.warn=[];showLd(true);prog(3,"Connecting to LIFE ERP…");
 const lbtn=document.getElementById("d_load");if(lbtn)lbtn.disabled=true;
 try{
  let who="";
  try{who=await api("frappe.auth.get_logged_user")}catch(e){throw new Error("LIFE ERP is not reachable from this page. Open it inside the portal (portal.lifescc.com/client-info-Enrollment) while logged in.")}
  if(!who||who==="Guest")throw new Error("You are not logged in. Log in to portal.lifescc.com, then reload this page.");
  LIVE.user=who;
  const uc=document.getElementById("userchip");if(uc)uc.textContent="👤 "+((window.frappe&&frappe.session&&frappe.session.user_fullname)||who);

  /* Load masters in background. Never block first visible register. */
  let mastersPromise=null;
  if(!LIVE.mastersOK){
   mastersPromise=loadMasters()
    .then(()=>{LIVE.mastersOK=true})
    .catch(e=>{warn("Masters — "+e.message);console.warn("[ENR] masters",e)});
  }

  prog(10,"Loading enrollments…");
  const pf=[["branch","not in",CFG.EXCLUDED]];
  if(from)pf.push(["start_date",">=",from]);
  if(to)pf.push(["start_date","<=",to]);

  const plans=(await gl("Therapy Plan",pf,["name","patient","patient_name","category","status","start_date","due_date","branch",
   "consultant_name","custom_employee_name","tele_caller","media","custom_total_plan_amount","total_sessions","total_sessions_completed",
   "custom_health_status","custom_client_record_number","custom_transfer_branch","therapy_plan_template","therapy_plan_already_taken_",
   "custom_is_expired","custom_is_inactive","invoiced","creation","owner"],{order:"start_date desc"})).filter(p=>p.patient);

  const ids=plans.map(p=>p.name), pids=[...new Set(plans.map(p=>p.patient))];
  prog(24,plans.length+" enrollments found · loading core details…");

  /*
   * FAST CORE LOAD
   * Only data required for the first usable table is awaited here.
   * Sessions, appointments, history, followups, concerns and receipts are
   * linked after the overlay closes so the page becomes usable much sooner.
   */
  let coreDone=0;
  const coreTick=t=>{coreDone++;prog(24+coreDone*14,t)};
  const [lines,invs,pts]=await Promise.all([
   safe(glIn("Therapy Plan Detail","parent",ids,[],["parent","idx","therapy_type","no_of_sessions","sessions_completed","custom_plan_amount"],{parent:"Therapy Plan"}),[],"Treatment lines").then(x=>{coreTick("Treatment lines linked");return x}),
   safe(glIn("Sales Invoice","therapy_plan_reference_id",ids,[["docstatus","=",1]],["name","therapy_plan_reference_id","posting_date","due_date","total","net_total","grand_total","rounded_total","disable_rounded_total","discount_amount","outstanding_amount","is_return","status","custom_tele_caller","custom_comp_limit_","custom_comp_used_"]),[],"Sales Invoice").then(x=>{coreTick("Invoices linked");return x}),
   safe(glIn("Patient","name",pids,[],["name","patient_name","mobile","phone","email","sex","dob","card_no","custom_pd_form_number","custom_thyroid","custom_diabetes","custom_diabete","custom_pcodpcos","custom_bp","custom_anemia","custom_recent_surgery","custom_heart_conditions","custom_weightin_kg","custom_vip_category","custom_profile_type","custom_vip_remarks","status"]),[],"Patient").then(x=>{coreTick("Client profiles linked");return x})
  ]);

  prog(78,"Opening register…");
  const base={lines,invs,sess:[],pts,hist:[],aps:[],fus:[],cmps:[],refs:[],pes:[]};
  buildRows(plans,base);
  LIVE.loaded=true;LIVE.from=from;LIVE.to=to;
  LIVE.at=new Date().toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"});
  afterLoad();
  prog(100,"Ready");

  /* Close the blocking overlay immediately after the core register is usable. */
  LIVE.busy=false;
  showLd(false);
  if(lbtn)lbtn.disabled=false;

  /* Background operational linking. These refresh the same rows in place. */
  (async()=>{
   try{
    dstat("● Live · "+plans.length+" enrollments · linking sessions & appointments…","ok");
    const [sess,hist,ap1,ap2]=await Promise.all([
     safe(glIn("Therapy Session","therapy_plan",ids,[["docstatus","=",1]],["name","therapy_plan","start_date","custom_actual_session_date","before_weight","after_weight","custom_inch_loss","service_unit"]),[],"Therapy Session"),
     safe(glIn("Therapy Plan","patient",pids,[],["name","patient","start_date","creation","custom_employee_name","category"]),[],"Enrollment history"),
     safe(glIn("Patient Appointment","therapy_plan_1",ids,[],["name","therapy_plan_1","appointment_date","call_back_status","status"]),[],"Appointments"),
     safe(glIn("Patient Appointment","therapy_plan",ids,[],["name","therapy_plan","appointment_date","call_back_status","status"]),[],"Appointments (plan link)")
    ]);

    if(!LIVE.loaded)return;
    const liveIds=new Set(DATA.map(x=>x.id));
    if(liveIds.size!==plans.length||plans.some(p=>!liveIds.has(p.name)))return;

    base.sess=sess;
    base.hist=hist;
    base.aps=ap1.concat(ap2);
    buildRows(plans,base);
    render();

    /* Remaining optional detail sources are already non-blocking. */
    await enrichRegisterRows(plans,pids,invs,base);

    LIVE.at=new Date().toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"});
    if(typeof afterLoad==="function")afterLoad();
   }catch(e){
    console.warn("[ENR] background operational link",e);
   }
  })();

  /* Enrich labels when masters finish, also without blocking the screen. */
  if(mastersPromise){
   mastersPromise.then(()=>{
    if(!LIVE.loaded)return;
    try{buildRows(plans,base);render()}catch(e){console.warn("[ENR] master refresh",e)}
   });
  }

 }catch(e){
  console.error("[ENR]",e);
  dstat("⚠ "+cln(e.message),"bad");
  document.getElementById("emp").style.display="block";
  document.getElementById("emp").innerHTML=`<div class="e1">Live data could not be loaded</div><div>${cln(e.message)}</div><div style="margin-top:10px"><button class="btn pri" onclick="loadLive()">⟳ Try again</button></div>`;
  document.getElementById("tbl").style.display="none";
  LIVE.busy=false;showLd(false);if(lbtn)lbtn.disabled=false;
 }
}

