/* ═══════════ BUILD REGISTER ROWS ═══════════ */
function buildRows(plans,S){
 DATA.length=0;
 const grp=(a,k)=>{const m={};(a||[]).forEach(x=>{const v=x[k];if(v)(m[v]=m[v]||[]).push(x)});return m};
 const PL=grp(S.lines,"parent"), IV=grp(S.invs,"therapy_plan_reference_id"), SS=grp(S.sess,"therapy_plan");
 const HI=grp(S.hist,"patient"), CM=grp(S.cmps,"client_name");
 const PT={};(S.pts||[]).forEach(p=>{PT[p.name]=p});
 const FU={};(S.fus||[]).forEach(x=>{FU[x.client]=iso10(x.last)});
 const AP={},seenA={};
 (S.aps||[]).forEach(a=>{if(seenA[a.name])return;seenA[a.name]=1;const k=a.therapy_plan_1||a.therapy_plan;if(!k)return;
  if(/cancel/i.test((a.call_back_status||"")+" "+(a.status||"")))return;(AP[k]=AP[k]||[]).push(iso10(a.appointment_date))});
 const PE={};(S.pes||[]).forEach(p=>{PE[p.name]=p});
 const RC={};(S.refs||[]).forEach(r=>{const pe=PE[r.parent];if(!pe)return;
  (RC[r.reference_name]=RC[r.reference_name]||[]).push({d:iso10(pe.posting_date),amt:Math.round(N(r.allocated_amount)),mode:cln(pe.mode_of_payment)||"—",ref:pe.name})});
 Object.values(HI).forEach(a=>a.sort((x,y)=>String(x.start_date||"").localeCompare(String(y.start_date||""))||String(x.creation||"").localeCompare(String(y.creation||""))));
 const payable=i=>(!N(i.disable_rounded_total)&&N(i.rounded_total))?N(i.rounded_total):N(i.grand_total);
 const MEDF=[["custom_pcodpcos","PCOD"],["custom_thyroid","Thyroid"],["custom_diabetes","Diabetic"],["custom_diabete","Diabetic"],["custom_bp","Hypertension"],["custom_anemia","Anaemia"],["custom_heart_conditions","Heart condition"],["custom_recent_surgery","Post Surgery"]];

 plans.forEach(p=>{
  const pt=PT[p.patient]||{};
  const bn=cln(p.branch)||"—", bc=CFG.BRANCH[bn];
  const code=bc?bc[0]:(bn.split(/\s+/).map(w=>w[0]||"").join("").toUpperCase().slice(0,3)||"—");
  const cl=bc?bc[1]:"Other";
  const bm=(LIVE.bm[bn]||[]).join(" / ")||"—";

  /* ── invoices & money ── */
  const all=IV[p.name]||[], ivs=all.filter(i=>!N(i.is_return)), rets=all.filter(i=>N(i.is_return));
  const nobill=!ivs.length;
  const disc=Math.round(ivs.reduce((s,i)=>s+N(i.discount_amount),0));
  let net=Math.round(all.reduce((s,i)=>s+payable(i),0));
  let pkg=net+disc;
  if(nobill){pkg=Math.round(N(p.custom_total_plan_amount));net=pkg}
  const due=nobill?0:Math.max(0,Math.round(all.reduce((s,i)=>s+N(i.outstanding_amount),0)));
  const paid=nobill?0:Math.max(0,net-due);
  const dpc=pkg?Math.round(disc/pkg*100):0;
  const rcpt=[];ivs.forEach(i=>(RC[i.name]||[]).forEach(x=>rcpt.push(x)));rcpt.sort((a,b)=>a.d.localeCompare(b.d));
  const rsum=rcpt.reduce((s,x)=>s+x.amt,0);
  if(paid>0&&rsum<paid-1)rcpt.push({d:iso10((ivs[0]||{}).posting_date),amt:paid-rsum,mode:"Settled on invoice",ref:(ivs[0]||{}).name||"—"});
  const mode=rcpt.length?(new Set(rcpt.map(x=>x.mode)).size>1?"Mixed":rcpt[0].mode):"—";
  const openDue=ivs.filter(i=>N(i.outstanding_amount)>0&&i.due_date).map(i=>iso10(i.due_date)).sort();
  const nextDue=due>0?(openDue[0]||""):"";
  const invSorted=ivs.slice().sort((a,b)=>String(b.posting_date).localeCompare(String(a.posting_date)));

  /* ── treatment lines ── */
  let ls=(PL[p.name]||[]).slice().sort((a,b)=>N(a.idx)-N(b.idx));
  if(!ls.length)ls=[{therapy_type:(catClean(p.category)||"Therapy")+" plan",no_of_sessions:p.total_sessions,sessions_completed:p.total_sessions_completed,custom_plan_amount:p.custom_total_plan_amount}];
  const wsum=ls.reduce((s,l)=>s+(N(l.custom_plan_amount)||N(l.no_of_sessions)||1),0)||1;
  const lines=ls.map(l=>{
   const t=cln(l.therapy_type)||"Therapy", T=LIVE.tt[l.therapy_type]||{};
   const m=mainOfType(l.therapy_type,p.category);
   const ses=Math.max(1,N(l.no_of_sessions)), done=Math.min(ses,N(l.sessions_completed));
   const sh=(N(l.custom_plan_amount)||N(l.no_of_sessions)||1)/wsum;
   const gross=Math.round(pkg*sh), dis=Math.round(disc*sh), lnet=Math.round(net*sh);
   const part=cln(T.custom_body_part)||(t.indexOf(" - ")>-1?cln(t.split(" - ").slice(1).join(" - ")):"—");
   const g=cln(T.custom_therapy_group)||catClean(T.healthcare_service_unit||p.category)||MSH[m]||m;
   const s=cln(T.custom_sub_group)||g;
   const o={m:m,g:g,s:s,base:t,item:t+" ("+ses+" sess)",part:part,unit:"Session",ses:ses,done:done,
    rate:Math.round(gross/ses),gross:gross,dis:dis,net:lnet,rn:Math.round(lnet/ses)};
   o.used=o.done*o.rn;o.bal=o.net-o.used;o.pct=Math.round(o.done/o.ses*100);
   return o;
  });
  const byNet={};lines.forEach(l=>{byNet[l.m]=(byNet[l.m]||0)+l.net+1});
  const main=mainNorm(p.category)&&lines.every(l=>l.m===mainNorm(p.category))?mainNorm(p.category):Object.keys(byNet).sort((a,b)=>byNet[b]-byNet[a])[0];

  /* ── sessions, visits, weight ── */
  const ss=(SS[p.name]||[]).map(s=>Object.assign({},s,{d:iso10(s.custom_actual_session_date||s.start_date)})).filter(s=>s.d).sort((a,b)=>a.d.localeCompare(b.d));
  const vis=ss.length, last=vis?ss[vis-1].d:"", first=vis?ss[0].d:"";
  const sesB=Math.max(N(p.total_sessions),lines.reduce((s,l)=>s+l.ses,0))||1;
  const sesC=Math.min(sesB,Math.max(N(p.total_sessions_completed),lines.reduce((s,l)=>s+l.done,0)));
  const pct=Math.round(sesC/sesB*100);
  const isSlim=main==="Slimming"||ss.some(s=>/slim/i.test(s.service_unit||""));
  let wJ=0,wP=0,il=0;
  ss.forEach(s=>{const b=N(s.before_weight),a=N(s.after_weight);if(!wJ&&b>0)wJ=b;if(a>0)wP=a;else if(b>0)wP=b;il+=N(s.custom_inch_loss)});
  if(!wJ&&isSlim&&N(pt.custom_weightin_kg)>0)wJ=N(pt.custom_weightin_kg);
  const wl=(wJ&&wP)?Math.round((wJ-wP)*10)/10:null;

  /* ── appointments ── */
  const ad=(AP[p.name]||[]).filter(Boolean).sort();
  const apt=ad.length, next=ad.find(d=>d>=TODAY)||"";

  /* ── history → joining category, joined by / rebooked by ── */
  const h=HI[p.patient]||[], ix=h.findIndex(x=>x.name===p.name);
  const earlier=ix>0?h.slice(0,ix):[];
  const rebook=earlier.length;
  let cat;
  if(p.custom_transfer_branch&&p.branch&&p.custom_transfer_branch!==p.branch)cat="Branch Transfer";
  else if(!rebook&&!N(p.therapy_plan_already_taken_))cat=/refer/i.test(p.media||"")?"Referral Join":(/existing/i.test(p.media||"")?"Renewal":"New Joining");
  else if(!rebook)cat="Renewal";
  else{const pm=earlier.map(x=>mainNorm(x.category));cat=pm.includes(main)||pm.includes(mainNorm(p.category))?"Rebooking":"Cross Sell (C2C)"}
  const jby=rebook?(cln(earlier[0].custom_employee_name)||"—"):(cln(p.custom_employee_name)||"—");
  const rby=rebook?(cln(p.custom_employee_name)||"—"):"—";

  /* ── medical ── */
  const mf=[...new Set(MEDF.filter(x=>N(pt[x[0]])).map(x=>x[1]))];
  const hs=String(p.custom_health_status||"");
  const med=mf.length?mf[0]:(hs==="Medical"?"Under Review":(hs==="Non-Medical"?"Fit":"Not recorded"));

  /* ── status & regularity ── */
  const enrolled=iso10(p.start_date)||iso10(p.creation);
  const start=first||enrolled;
  let status;
  if(/cancel/i.test(p.status||"")||N(p.custom_is_inactive)||N(p.custom_is_expired))status="Deactivated";
  else if(pct>=100||p.status==="Completed")status="Completed";
  else{const g=dayDiff(last||enrolled,TODAY);status=(g!==null&&g>CFG.BREAK_DAYS)?"Break":"Active"}
  const months=Math.max(1,Math.round((dayDiff(start,TODAY)||0)/30));
  const amv=+(vis/months).toFixed(1);

  /* ── concerns ── */
  const cm=(CM[p.patient]||[]).slice().sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")));
  const cmpOpen=cm.filter(c=>!/(closed|resolved|completed|rejected)/i.test((c.complaint_status||"")+" "+(c.workflow_state||""))).length;

  /* ── dob → age ── */
  let age=NaN;if(pt.dob){const a=dayDiff(iso10(pt.dob),TODAY);if(a!==null&&a>0)age=Math.floor(a/365.25)}
  const sx=String(pt.sex||"");
  const mob=dig(pt.mobile), alt=dig(pt.phone);

  DATA.push({
   id:p.name, pid:cln(p.patient), plan:p.name, pstat:p.status||"",
   name:cln(p.patient_name||pt.patient_name||p.patient), mob:mob, alt:alt&&alt!==mob?alt:"",
   gen:/^f/i.test(sx)?"Female":(/^m/i.test(sx)?"Male":"—"), age:age,
   br:code, brn:bn, cl:cl, bm:bm,
   jby:jby, rby:rby,
   pkg:pkg, disc:disc, dpc:dpc, net:net, paid:paid, due:due, rcpt:rcpt, nobill:nobill,
   enrolled:enrolled, start:start, med:med, medAll:mf.join(", ")||med,
   cons:LIVE.prac[p.consultant_name]||cln(p.consultant_name)||"—",
   cc:cln(p.tele_caller)||cln((ivs[0]||{}).custom_tele_caller)||"—",
   acts:[], actsLoaded:false,
   pd:cln(pt.custom_pd_form_number)||"—", pdok:!!cln(pt.custom_pd_form_number),

   /* Patient premium-profile fields */
   vipCategory:cln(pt.custom_vip_category),
   profileType:cln(pt.custom_profile_type),
   vipRemarks:cln(pt.custom_vip_remarks),

