 const seen={};BR=[];
 Object.keys(CFG.BRANCH).forEach(n=>{const b={c:CFG.BRANCH[n][0],n:n,cl:CFG.BRANCH[n][1],bm:(LIVE.bm[n]||[]).join(" / ")||"—"};BR.push(b);seen[b.c]=1});
 DATA.forEach(r=>{if(!seen[r.br]){seen[r.br]=1;BR.push({c:r.br,n:r.brn,cl:r.cl,bm:r.bm})}});
 CONS=uniq(DATA.map(r=>r.cons));CC=uniq(DATA.map(r=>r.cc));
