/* ═══════════ FINANCIAL ENGINE — value, delivery and category breakup ═══════════ */
function fin(r){
 const perS=r.sesB?Math.round(r.net/r.sesB):0;
 const used=r.lines.reduce((s,l)=>s+l.used,0);          // value of sessions delivered
 const unused=Math.max(0,r.net-used);                    // value still to be delivered
 const paidSess=r.paid>=r.net?r.sesB:(perS?Math.min(r.sesB,Math.floor(r.paid/perS)):0);   // sessions the money covers
 const dueSess=Math.max(0,r.sesB-paidSess);
 const ahead=Math.max(0,used-r.paid);                    // service given ahead of money
 const advance=Math.max(0,r.paid-used);                  // money held against future sessions
 const map={};
 r.lines.forEach(l=>{
  const k=l.m; map[k]=map[k]||{m:k,items:0,ses:0,done:0,gross:0,dis:0,net:0,used:0,names:[]};
  const o=map[k]; o.items++; o.ses+=l.ses; o.done+=l.done; o.gross+=l.gross; o.dis+=l.dis;
  o.net+=l.net; o.used+=l.used; o.names.push(l.item);
 });
 const lines=r.lines.map(l=>{
  const sh=r.net?l.net/r.net:0, pv=Math.round(r.paid*sh);
  const ps=pv>=l.net?l.ses:(l.rn?Math.min(l.ses,Math.floor(pv/l.rn)):0);
  return Object.assign({},l,{paidV:pv,paidSess:ps,unpaidSess:l.ses-ps,unpaidV:Math.max(0,l.net-pv),
    dueSess:Math.max(0,ps-l.done),share:Math.round(sh*100)});
 });
 const by=Object.values(map).sort((a,b)=>b.net-a.net);
 by.forEach(o=>{
  const sh=r.net?o.net/r.net:0;
  o.share=Math.round(sh*100);
  o.paid=Math.round(r.paid*sh);
  o.due=Math.max(0,o.net-o.paid);
  o.bal=Math.max(0,o.net-o.used);
  o.upct=o.net?Math.round(o.used/o.net*100):0;
  o.ppct=o.net?Math.round(o.paid/o.net*100):0;
 });
 return {perS,used,unused,paidSess,dueSess,ahead,advance,by,lines,
  colPct:r.net?Math.round(r.paid/r.net*100):0,
  delPct:r.net?Math.round(used/r.net*100):0};
}

