 if(q==="vip" && tierOf(r)!=="VIP")return false;
 if(q==="vvip" && tierOf(r)!=="VVIP")return false;
 if(q==="hni" && tierOf(r)!=="HNI")return false;
 /* Backward compatibility if an old combined chip is still present briefly. */
 if(q==="tier" && !tierOf(r))return false;
