 if(q==="done" && r.status!=="Completed")return false;
 if(q==="nobill" && !r.nobill)return false;
 if(vertMode!=="all" && r.main!==vertMode)return false;

 const from=v("f_from"), to=v("f_to");
 if(from && r.enrolled<from)return false;
 if(to && r.enrolled>to)return false;
