 if(nd==="Overdue"&&!(nds!==null&&nds<0))return false;
 if(nd==="Due in 7 days"&&!(nds!==null&&nds>=0&&nds<=7))return false;
 if(nd==="Due in 30 days"&&!(nds!==null&&nds>=0&&nds<=30))return false;
 const wf=v("f_wl");
 if(wf!=="All"){
  if(wf==="Lost 1 kg +"&&!(r.wl>=1))return false;
  if(wf==="Lost 3 kg +"&&!(r.wl>=3))return false;
  if(wf==="Lost 5 kg +"&&!(r.wl>=5))return false;
  if(wf==="Weight gain"&&!(r.wl<0))return false;
  if(wf==="No weight record"&&!(r.isSlim&&r.wl==null))return false;
  if(wf==="Inch loss recorded"&&!(r.il>0))return false;
 }
 return true;
}

const SORTV={sn:r=>r.enrolled,cli:r=>r.name,act:r=>r.name,ga:r=>r.age,brm:r=>r.br,jr:r=>r.jby,pk:r=>r.pkg,
 pd_:r=>r.due,dt:r=>r.start,med:r=>r.med,cn:r=>r.cons,pdf:r=>r.pd,cat:r=>r.cat,pln:r=>r.main,
 lv:r=>r.last,sts:r=>r.status,due:r=>r.nextDue||"9999",ses:r=>r.sesC,apt:r=>r.vis,inv:r=>r.inv,rbx:r=>r.rebook,crd:r=>r.card,ref:r=>r.refG,cr:r=>r.crE,cmp:r=>r.cmp,wt:r=>r.wl==null?-999:r.wl,amv:r=>r.amv,ct:r=>r.ct,zs:r=>r.zs,pct:r=>r.pct};

function filtered(){
 let a=DATA.filter(match);
 if(sortK&&SORTV[sortK]){const f=SORTV[sortK];a=a.slice().sort((x,y)=>{const p=f(x),q=f(y);return (p>q?1:p<q?-1:0)*sortD})}
 return a;
}

/* ═══════════ RENDER ═══════════ */
function donut(p){
 const c=2*Math.PI*8, off=c*(1-p/100);
 const col=p>=75?"#178a5f":p>=40?"#b7791f":p===0?"#c0392b":"#c2691a";
 return `<svg width="22" height="22" viewBox="0 0 22 22"><circle cx="11" cy="11" r="8" fill="none" stroke="#e9f0ec" stroke-width="3.2"></circle><circle cx="11" cy="11" r="8" fill="none" stroke="${col}" stroke-width="3.2" stroke-dasharray="${c}" stroke-dashoffset="${off}" transform="rotate(-90 11 11)" stroke-linecap="round"></circle></svg>`;
}
function ubar(r){
 const p=Math.max(0,Math.min(100,r.pct)), c=p===0?"u0":p<25?"u1":p<60?"u2":p<100?"u3":"u4";
 return `<div class="ubr" title="Sessions utilised: ${r.sesC} of ${r.sesB} (${p}%) · balance ${r.sesB-r.sesC}"><i class="${c}" style="width:${Math.max(p,p?4:0)}%"></i><span>${r.sesC}/${r.sesB} sessions · ${p}% used</span></div>`;
}
function clientOverallPackageAmount(r){
 /*
  * Premium classification is CLIENT LEVEL, not Therapy Plan level.
  * Sum every package row belonging to the same Patient ID.
  *
  * Example:
  *   Package 1 = ₹80,000
  *   Package 2 = ₹90,000
  *   Package 3 = ₹1,00,000
  *   Overall   = ₹2,70,000 => VVIP
  */
 const pid=String(r&&r.pid||"").trim();

 if(!pid){
  return Number(r&&r.pkg)||0;
 }

 return DATA.reduce((sum,row)=>{
  if(String(row&&row.pid||"").trim()!==pid)return sum;
  return sum+(Number(row.pkg)||0);
 },0);
}

function clientOverallPackageCount(r){
 const pid=String(r&&r.pid||"").trim();
 if(!pid)return r?1:0;

 return DATA.reduce((count,row)=>
  count+(String(row&&row.pid||"").trim()===pid?1:0)
 ,0);
}

function clientOverallPlans(r){
 const pid=String(r&&r.pid||"").trim();

 if(!pid){
  return r&&r.plan?[String(r.plan)]:[];
 }

 const seen=new Set();
 const out=[];

 DATA.forEach(row=>{
  if(String(row&&row.pid||"").trim()!==pid)return;

  const p=String(row.plan||row.id||"").trim();
  if(!p || seen.has(p))return;

  seen.add(p);
  out.push(p);
 });

 return out;
}

function tierOf(r){
 /*
  * PREMIUM TIER RULE — calculated from ALL package values of the client.
  *
  * VIP  : ₹2,00,000 to below ₹2,50,000
  * VVIP : ₹2,50,000 to ₹5,00,000 inclusive
  * HNI  : above ₹5,00,000
  *
  * Patient.custom_vip_category is NOT used to override this calculation.
  * This keeps the dashboard tier aligned with the client's current overall
  * package value.
  */
 const total=clientOverallPackageAmount(r);

 if(total>500000)return "HNI";
 if(total>=250000)return "VVIP";
 if(total>=200000)return "VIP";

 return "";
}
function tierB(r){const t=tierOf(r);return t?`<span class="tier t-${t.toLowerCase()}">${t}</span>`:""}
function medB(m){const cl=m==="Not recorded"?"b-gr":m==="Fit"?"b-ok":(m==="Pregnancy Hold"||m==="Under Review"||m==="Post Surgery")?"b-cr":"b-wa";return `<span class="bdg ${cl}">${m}</span>`}
function catB(c){const m={"New Joining":"b-ok","Rebooking":"b-in","Renewal":"b-pu","Upgrade":"b-or","Cross Sell (C2C)":"b-wa","Referral Join":"b-ok","Branch Transfer":"b-gr","Corporate / B2B":"b-in"};return `<span class="bdg ${m[c]||"b-gr"}">${c.replace(" (C2C)"," C2C").replace("Corporate / B2B","B2B")}</span>`}
function ctB(c){const m={Call:"b-ok",Message:"b-in",Mail:"b-pu",DND:"b-cr"};return `<span class="bdg ${m[c]}">${c}</span>`}

