 document.getElementById("thr").innerHTML=on.map(c=>
  `<th class="${c.k==="eye"||c.k==="sn"?"nos":""}${c.k==="sn"?" stk s1":c.k==="cli"?" stk s2":""}" ${c.k!=="eye"&&c.k!=="sn"?`onclick="sortBy('${c.k}')"`:""} title="${c.t} · ${c.s}">${c.t}${sortK===c.k?(sortD>0?" ▲":" ▼"):""}<span class="h2l">${c.s}</span></th>`).join("");

 document.getElementById("tb").innerHTML=sl.map((r,i)=>
  `<tr class="${r.zs?"zs":""}">${on.map(c=>cell(c.k,r,st+i+1)).join("")}</tr>`).join("");

 document.getElementById("emp").style.display=rows.length?"none":"block";
 document.getElementById("tbl").style.display=rows.length?"":"none";

 document.getElementById("cnt").innerHTML=rows.length
  ?`Showing <b>${st+1}–${Math.min(st+pp,rows.length)}</b> of <b>${rows.length}</b> enrollments${rows.length!==DATA.length?` <span class="hint">(filtered from ${DATA.length})</span>`:""}`
  :`<b>0</b> of ${DATA.length} enrollments`;

 // pager
 let h=`<button class="pg" ${page===1?"disabled":""} onclick="go(1)">« First</button>
        <button class="pg" ${page===1?"disabled":""} onclick="go(${page-1})">‹ Prev</button>`;
 const nums=[];
 for(let i=1;i<=tp;i++){if(i===1||i===tp||Math.abs(i-page)<=2)nums.push(i);else if(nums[nums.length-1]!=="…")nums.push("…")}
 nums.forEach(n=>{h+= n==="…"?`<span class="pgd">…</span>`:`<button class="pg ${n===page?"on":""}" onclick="go(${n})">${n}</button>`});
 h+=`<button class="pg" ${page===tp?"disabled":""} onclick="go(${page+1})">Next ›</button>
     <button class="pg" ${page===tp?"disabled":""} onclick="go(${tp})">Last »</button>
     <div style="flex:1"></div><span class="hint">Page ${page} of ${tp} · ${pp} rows per page · sort by clicking any header</span>`;
 document.getElementById("pager").innerHTML=h;

 fsum(rows.length);
 renderReports();
}

