function premiumTierRows(mode){
 const code=premiumTierMeta(mode).code;
 const grouped=new Map();

 DATA.forEach(r=>{
  const pid=String(r.pid||"").trim();
  if(!pid)return;

  if(!grouped.has(pid)){
   grouped.set(pid,{
    representative:r,
    totalPackage:0,
    totalDue:0,
    packageCount:0,
    plans:[],
    planSet:new Set()
   });
  }

  const g=grouped.get(pid);

  g.totalPackage+=Number(r.pkg)||0;
  g.totalDue+=Number(r.due)||0;
  g.packageCount+=1;

  const plan=String(r.plan||r.id||"").trim();
  if(plan && !g.planSet.has(plan)){
   g.planSet.add(plan);
   g.plans.push(plan);
  }

  /*
   * Prefer the newest row as the representative record because DATA is
   * already sorted newest-first after load.
   */
 });

 const rows=[];

 grouped.forEach(g=>{
  const r=Object.assign({},g.representative,{
   pkg:g.totalPackage,
   due:g.totalDue,
   overallPackage:g.totalPackage,
   packageCount:g.packageCount,
   allClientPlans:g.plans
