 try{
  const rows=await api("frappe.client.get_list",{
   doctype:"Patient",
   fields:["name","patient_name","mobile","phone"],
   filters:[],
   or_filters:[
    ["Patient","name","like",like],
    ["Patient","patient_name","like",like],
    ["Patient","mobile","like",like],
    ["Patient","phone","like",like]
   ],
   order_by:"modified desc",
   limit_start:0,
   limit_page_length:20
  });
  return Array.isArray(rows)?rows:[];
 }catch(e){
  try{
   const out=await api("frappe.desk.search.search_link",{
    doctype:"Patient",txt:q,page_length:20,reference_doctype:"Patient"
   });
   const rows=(out&&out.results)||out||[];
   return (Array.isArray(rows)?rows:[]).map(x=>({
    name:x.value||x.name||"",
    patient_name:x.label||x.value||x.name||"",
    mobile:"",phone:""
   }));
  }catch(e2){
   console.warn("[ENR GLOBAL SEARCH]",e,e2);
   return [];
  }
 }
