 u.searchParams.set("client_name",r.name||"");
 u.searchParams.set("mobile",r.mob||"");
 u.searchParams.set("therapy_plan",r.plan||r.id||"");
 u.searchParams.set("branch",r.brn||r.br||"");

 /* Dashboards which already understand URL context. */
 if(it[0]==="Wellness evaluation session"){
  u.searchParams.set("mode","new");
 }
 if(it[0]==="Followup note")u.searchParams.set("mode","new-followup");
 if(it[0]==="Feedback")u.searchParams.set("mode","feedback");
 if(it[0]==="Due recovery followup")u.searchParams.set("mode","dues");
 return u.pathname+u.search;
}
function clientNeedles(r){
 return [String(r.pid||"").trim(),String(r.name||"").trim(),String(r.mob||"").trim()].filter(Boolean);
}
function fireTargetInput(w,el,value){
 try{
  const proto=el.tagName==="TEXTAREA"?w.HTMLTextAreaElement.prototype:w.HTMLInputElement.prototype;
  const setter=Object.getOwnPropertyDescriptor(proto,"value");
  if(setter&&setter.set)setter.set.call(el,value);else el.value=value;
  ["input","change","keyup"].forEach(t=>el.dispatchEvent(new w.Event(t,{bubbles:true})));
 }catch(e){try{el.value=value}catch(_){}}
}
function targetInputScore(el){
 const z=[el.id,el.name,el.placeholder,el.getAttribute("aria-label"),el.className].join(" ").toLowerCase();
 let n=0;
 if(/client|patient/.test(z))n+=100;
 if(/search|select|find/.test(z))n+=35;
 if(/mobile|phone/.test(z))n+=20;
 if(/global|navbar|awesomebar/.test(z))n-=160;
 if(el.type==="search")n+=8;
 return n;
}
function clickExactTargetMatch(w,d,r){
 const needles=clientNeedles(r).map(x=>x.toLowerCase());
 const nodes=Array.from(d.querySelectorAll(
  '[data-pick-follow],[data-client],[data-patient],[data-client-id],[data-patient-id],'+
  '.autocomplete-item,.awesomplete li,.dropdown-menu .dropdown-item,.list-group-item,'+
  '[role="option"],button,tr[data-name],div[data-name]'
 ));
 const exact=nodes.find(el=>{
  const raw=[
   el.dataset&&el.dataset.pickFollow,
   el.dataset&&el.dataset.client,
   el.dataset&&el.dataset.patient,
   el.dataset&&el.dataset.clientId,
   el.dataset&&el.dataset.patientId,
   el.dataset&&el.dataset.name,
   el.getAttribute&&el.getAttribute("data-value"),
   el.textContent
  ].join(" ").toLowerCase();
  return needles.some(n=>n&&raw.includes(n));
 });
 if(exact){try{exact.click();return true}catch(e){}}
 return false;
}

/* Wait until a newly-opened LIFE Web Page has finished loading.
   This stays entirely in the Enrollment Register script; destination scripts
   are not modified. */
function waitForTargetWindow(w,ready,run,label){
 let tries=0;
 const timer=setInterval(async()=>{
  tries++;
  if(!w||w.closed||tries>120){
   clearInterval(timer);
   if(tries>120)toast((label||"Dashboard")+" opened, but client auto-selection timed out");
   return;
  }
  try{
   if(!ready(w))return;
   clearInterval(timer);
   await run(w);
   try{w.focus()}catch(e){}
  }catch(e){
   console.warn("[ENR ACTION]",label,e);
  }
 },250);
}


