  .replace(/&/g,"&amp;")
  .replace(/</g,"&lt;")
  .replace(/>/g,"&gt;")
  .replace(/"/g,"&quot;")
  .replace(/'/g,"&#039;");
}

function patientInfoPopupLabel(key){
 return String(key||"")
  .replace(/^custom_/,"")
  .replace(/_/g," ")
  .replace(/\b\w/g,c=>c.toUpperCase());
}

function patientInfoPopupVisiblePairs(row){
 const skip=new Set([
  "name","owner","creation","modified","modified_by",
  "docstatus","idx","parent","parentfield","parenttype",
  "doctype","__islocal","__unsaved"
 ]);

 return Object.keys(row||{})
  .filter(k=>
   !skip.has(k) &&
   row[k]!==null &&
   row[k]!==undefined &&
   String(row[k]).trim()!==""
  )
  .map(k=>[patientInfoPopupLabel(k),row[k]]);
}

