async function savePatientInfoRemark(){
 const patientId=String(PATIENT_INFO_STATE.patientId||"").trim();
 const clientName=String(PATIENT_INFO_STATE.clientName||patientId).trim();
 const input=document.getElementById("patientInfoNewRemark");
 const btn=document.getElementById("patientInfoSaveRemark");
 const err=document.getElementById("patientInfoRemarkError");

 if(err){
  err.style.display="none";
  err.textContent="";
 }

 const text=String((input&&input.value)||"").trim();

 if(!patientId){
  if(err){
   err.style.display="block";
   err.textContent="Patient ID is missing.";
  }
  return;
 }

 if(!text){
  if(err){
   err.style.display="block";
   err.textContent="Write a client remark before saving.";
  }
  if(input)input.focus();
  return;
 }

 try{
  if(btn){
   btn.disabled=true;
   btn.textContent="Saving…";
  }

  const doc=await api("frappe.client.get",{
   doctype:"Patient",
   name:patientId
  });

  if(!doc){
   throw new Error("Client/Patient not found.");
  }

  if(!Array.isArray(doc.custom_client_remarks_)){
   doc.custom_client_remarks_=[];
  }

  const fieldname=patientInfoRemarkField(
   doc.custom_client_remarks_
  );

  const row={
   doctype:"Remarks"
  };

  row[fieldname]=text;

  doc.custom_client_remarks_.push(row);

  await api("frappe.client.save",{
   doc:doc
  });

  toast("Client remark saved for "+clientName);

  await openPatientInfoPopup(
   patientId,
   clientName,
   "remarks"
  );

 }catch(e){
  if(err){
   err.style.display="block";
   err.textContent=
    (e&&e.message)||
    "Unable to save client remark.";
  }
 }finally{
  if(btn){
   btn.disabled=false;
   btn.textContent="💾 Save remark";
  }
 }
}


