/* ═════════════════════════════════════════════════════════════════════════════
   REFERRAL DETAILS POPUP — CLIENT INFO / CLIENT-360 LOGIC

   IMPORTANT:
   - Do not invent referral field names.
   - Primary live audit source is Sales Invoice.remarks.
   - Client referral audit:   Referred by client: Client Name (Patient-ID)
   - Employee referral audit: Referred by employee: Employee Name
   - Existing Patient / Therapy Plan referral values are discovered from the
     loaded documents themselves, matching Client Info's referralInfo logic.

   Clicking Referral stays inside Enrollment Register and shows the exact
   "Joined through" referral name(s), followed by clients referred by this client.
   ═════════════════════════════════════════════════════════════════════════════ */

function referralEsc(v){
 return String(v==null?"":v)
  .replace(/&/g,"&amp;")
  .replace(/</g,"&lt;")
  .replace(/>/g,"&gt;")
  .replace(/"/g,"&quot;")
  .replace(/'/g,"&#039;");
}

function referralStripHtml(v){
 const d=document.createElement("div");
 d.innerHTML=String(v||"");
 return String(d.textContent||d.innerText||"")
  .replace(/\s+/g," ")
  .trim();
}

function referralLc(v){return String(v==null?"":v).trim().toLowerCase()}

function referralGenericValue(v){
 const s=referralLc(v);
 return !s||[
  "reference","referral","direct","direct walk-in","walk in","walk-in",
  "existing customer","call center","website","meta","social media"
 ].includes(s);
}

/* Exact Client Info client-referral parser. */
function referralInvoiceClient(inv){
 const raw=referralStripHtml(inv&&inv.remarks);
 if(!raw)return null;

 let m=raw.match(/Referred by client:\s*([^|]+?)\s*\(([^()]+)\)(?=\s*(?:\||$))/i);
 if(m){
  return {
   id:String(m[2]||"").trim(),
   name:String(m[1]||"").trim(),
   source:"Sales Invoice",
   kind:"client"
  };
 }

 m=raw.match(/Referred by client:\s*([^|]+)/i);
 if(m){
  return {
   id:"",
   name:String(m[1]||"").replace(/\s*\([^()]+\)\s*$/,"").trim(),
   source:"Sales Invoice",
   kind:"client"
  };
 }
 return null;
}

/* Exact Client Info employee-referral parser. */
function referralInvoiceEmployee(inv){
 const raw=referralStripHtml(inv&&inv.remarks);
 if(!raw)return null;
 const m=raw.match(/Referred by employee:\s*([^|]+?)(?=\s*(?:\||$))/i);
 if(!m)return null;
 const name=String(m[1]||"").trim();
 if(!name)return null;
 return {id:"",name:name,source:"Sales Invoice",kind:"employee"};
}

function referralInvoiceWasReferredBy(inv,patientId,patientName){
 const ref=referralInvoiceClient(inv);
 if(!ref)return false;
 const rid=referralLc(ref.id), rname=referralLc(ref.name);
 const pid=referralLc(patientId), pname=referralLc(patientName);
 return !!((pid&&rid===pid)||(pname&&rname===pname));
}

function referralUniquePush(arr,item){
 if(!item)return;
 const id=String(item.id||"").trim();
 const name=String(item.name||item.value||"").trim();
 if(!id&&!name)return;
 if(referralGenericValue(name))return;
 const key=referralLc(id||name);
 if(!arr.some(x=>referralLc(x.id||x.name)===key)){
  arr.push({
   id:id,
   name:name||id,
   source:item.source||"",
   kind:item.kind||""
  });
 }
}

/* Same Patient dynamic referral discovery used by Client Info referralInfo(). */
function referralPatientValues(patient){
 const out=[];
 Object.keys(patient||{}).forEach(k=>{
  if(!/(referr|refered|referred|reference_by|ref_by)/i.test(k))return;
  const v=patient[k];
  if(v&&(typeof v==="string"||typeof v==="number")){
   referralUniquePush(out,{id:"",name:String(v),source:"Patient",kind:""});
  }
 });
 return out;
}

/* Same compatibility idea as Client Info: discover client/patient referral keys
   from the actual Therapy Plan document instead of guessing query fields. */
function referralPlanValues(plan){
 const out=[];
 const idKeys=[];
 const nameKeys=[];
 Object.keys(plan||{}).forEach(k=>{
  const isReferral=/(referr|refered|referred|reference|ref_by)/i.test(k);
  const isClient=/(client|patient)/i.test(k);
  if(!isReferral||!isClient)return;
  if(/name/i.test(k))nameKeys.push(k);else idKeys.push(k);
 });
 const refId=idKeys.map(k=>plan[k]).find(Boolean)||"";
 const refName=nameKeys.map(k=>plan[k]).find(Boolean)||"";
 if(refId||refName){
  referralUniquePush(out,{
   id:String(refId||"").trim(),
   name:String(refName||refId||"").trim(),
   source:"Therapy Plan",
   kind:"client"
  });
 }
 return out;
}

async function referralResolveNames(rows){
 const out=[];
 for(const row of rows||[]){
  if(!row)continue;
  let id=String(row.id||"").trim();
  let name=String(row.name||"").trim();
  if(id&&(!name||name===id)){
   try{
    const p=await api("frappe.client.get",{doctype:"Patient",name:id});
    if(p)name=String(p.patient_name||p.name||name||id).trim();
   }catch(e){}
  }
  referralUniquePush(out,{id:id,name:name||id,source:row.source,kind:row.kind||""});
 }
 return out;
}

