async function openReferralPopup(enrollmentId){
 const r=DATA.find(x=>x.id===enrollmentId);
 if(!r){toast("Enrollment record not found");return}

 const pid=String(r.pid||"").trim();
 const pname=String(r.name||pid).trim();
 if(!pid){toast("Patient ID is missing");return}

 const ov=ensureReferralPopup();
 const body=ov.querySelector("#referralInfoBody");
 ov.querySelector("#referralInfoTitle").textContent=pname+" — Referral";
 ov.querySelector("#referralInfoSub").textContent=pid+" · same referral source and naming logic as Client Info";
 body.innerHTML='<div style="padding:30px;text-align:center;color:#718078">Loading Client Info referral…</div>';
 ov.style.display="block";

 try{
  const reqs=[
   api("frappe.client.get_list",{
    doctype:"Sales Invoice",
    filters:[["patient","=",pid],["docstatus","=",1]],
    fields:["name","patient","patient_name","posting_date","creation","remarks"],
    order_by:"posting_date desc",
    limit_page_length:2000
   }),
   api("frappe.client.get",{doctype:"Patient",name:pid}),
   api("frappe.client.get",{doctype:"Therapy Plan",name:String(r.plan||r.id||"")})
  ];

  const got=await Promise.all(reqs.map(p=>p.catch(()=>null)));
  const ownInvoices=Array.isArray(got[0])?got[0]:[];
  const patient=got[1]||{};
  const plan=got[2]||{};

  let joinedThrough=[];
  referralPatientValues(patient).forEach(x=>referralUniquePush(joinedThrough,x));
  ownInvoices.forEach(inv=>{
   const clientRef=referralInvoiceClient(inv);
   if(clientRef)referralUniquePush(joinedThrough,clientRef);
   const employeeRef=referralInvoiceEmployee(inv);
   if(employeeRef)referralUniquePush(joinedThrough,employeeRef);
  });
  referralPlanValues(plan).forEach(x=>referralUniquePush(joinedThrough,x));
  joinedThrough=await referralResolveNames(joinedThrough);

  const outgoingInvoices=[];
  const seenInvoices=new Set();
  const searches=[
   pid?"%Referred by client:%("+pid+")%":"",
   pname?"%Referred by client:"+pname+"%":""
  ].filter(Boolean);

  for(const q of searches){
   let rows=[];
   try{
    rows=await api("frappe.client.get_list",{
     doctype:"Sales Invoice",
     filters:[["docstatus","!=",2],["remarks","like",q]],
     fields:["name","patient","patient_name","posting_date","creation","remarks"],
     order_by:"posting_date desc",
     limit_page_length:500
    })||[];
   }catch(e){rows=[]}
   (Array.isArray(rows)?rows:[]).forEach(inv=>{
    if(!inv||seenInvoices.has(inv.name))return;
    seenInvoices.add(inv.name);
    outgoingInvoices.push(inv);
   });
  }

  const brought=[];
  outgoingInvoices.forEach(inv=>{
   if(!referralInvoiceWasReferredBy(inv,pid,pname))return;
   if(!inv.patient||String(inv.patient)===pid)return;
   if(!brought.some(x=>String(x.name)===String(inv.patient))){
    brought.push({
     name:inv.patient,
     patient_name:inv.patient_name||inv.patient,
     creation:inv.posting_date||inv.creation
    });
   }
  });

  body.innerHTML=
   '<div style="border:1px solid #dce8e1;border-radius:12px;padding:13px;background:#fbfdfb">'+
    '<div style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#718178;font-weight:900;margin-bottom:8px">Joined through</div>'+
    referralJoinedThroughHtml(joinedThrough)+
   '</div>'+
   referralBroughtHtml(brought,pname);

 }catch(e){
  body.innerHTML='<div style="padding:28px;text-align:center">'+
   '<div style="color:#a02c22;font-weight:900">Could not load Client Info referral</div>'+
   '<div style="margin-top:6px;color:#74827a">'+referralEsc((e&&e.message)||"Unknown error")+'</div>'+
  '</div>';
 }
}

