  const userNames={};
  if(userIds.length){
   const users=await safe(glIn("User","name",userIds,[],["name","full_name"],{limit:2000}),[],"Discount approver names");
   (users||[]).forEach(u=>{userNames[u.name]=u.full_name||u.name});
  }
  const who=u=>userNames[u]||u||"—";
