  function approvalBlock(x){
   if(!x.approvals.length)return '<div style="margin-top:7px;padding:7px 9px;border:1px dashed #dce8e1;border-radius:7px;color:#89978f;font-size:11px">No Discount Approval Request history found for this package invoice.</div>';
   return '<div style="margin-top:8px;border:1px solid #dce8e1;border-radius:8px;overflow:auto"><div style="padding:6px 8px;background:#f4faf7;font-size:11px;font-weight:900;color:#0b5138">Approval History</div><table style="width:100%;border-collapse:collapse;font-size:10.5px"><thead><tr style="background:#fbfdfc;color:#53665e"><th style="padding:6px;text-align:left">Level</th><th style="padding:6px;text-align:left">Status</th><th style="padding:6px;text-align:left">Approved / Actioned By</th><th style="padding:6px;text-align:right">Approved %</th><th style="padding:6px;text-align:right">This Level Discount</th><th style="padding:6px;text-align:right">Approved Final</th><th style="padding:6px;text-align:left">Date / Time</th></tr></thead><tbody>'+x.approvals.map(a=>{
    const level=String(a.approval_level||"—").toUpperCase();
    const actor=a.approved_by||a.selected_approver||"";
    const amt=approvalAmount(a);
    const pct=approvalPct(a);
    const finalAmt=N(a.approved_final_amount);
    const when=a.approved_at||a.creation||"";
    return '<tr style="border-top:1px solid #edf2ef"><td style="padding:6px;font-weight:900;color:#173f31">'+discountEsc(level)+'</td><td style="padding:6px">'+approvalStatusPill(a.status)+'</td><td style="padding:6px"><div style="font-weight:800;color:#173f31">'+discountEsc(who(actor))+'</div><div style="font-size:9.5px;color:#819087">'+discountEsc(actor)+'</div></td><td style="padding:6px;text-align:right;font-weight:800">'+(pct?pct.toFixed(2).replace(/\.00$/,'')+'%':'—')+'</td><td style="padding:6px;text-align:right;color:#b45309;font-weight:900">'+(amt?('−'+inr(amt)):'—')+'</td><td style="padding:6px;text-align:right;font-weight:800">'+(finalAmt?inr(finalAmt):'—')+'</td><td style="padding:6px;white-space:nowrap">'+discountEsc(when?String(when).replace('T',' ').slice(0,19):'—')+'</td></tr>';
   }).join("")+'</tbody></table></div>';
  }

  const table=rows.length?'<div style="overflow:auto;border:1px solid #dce8e1;border-radius:10px"><table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr style="background:#eef7f2;color:#06382a"><th style="padding:9px;text-align:left">Therapy Plan / Package</th><th style="padding:9px;text-align:left">Date</th><th style="padding:9px;text-align:left">Branch</th><th style="padding:9px;text-align:right">Actual Package</th><th style="padding:9px;text-align:right">Discount Given</th><th style="padding:9px;text-align:right">Disc %</th><th style="padding:9px;text-align:right">After Discount</th><th style="padding:9px;text-align:right">Paid</th><th style="padding:9px;text-align:right">Pending</th><th style="padding:9px;text-align:left">Invoice(s)</th></tr></thead><tbody>'+rows.map(x=>{
   const p=x.plan||{}, invNames=x.iv.length?x.iv.map(i=>'<button type="button" onclick="event.stopPropagation();openSalesInvoiceDirect(\''+discountEsc(i.name)+'\')" style="border:0;background:transparent;padding:0;color:#0d6b50;font-weight:800;text-decoration:underline;text-underline-offset:2px;cursor:pointer">'+discountEsc(i.name)+'</button>').join("<br>"):"—";
   const isCurrent=String(x.key)===String(r.plan||r.id||"");
   const noInvoice='<span style="color:#89978f">—</span>';
   return '<tr style="border-top:1px solid #e8efeb;'+(isCurrent?'background:#fff9df':'')+'"><td colspan="10" style="padding:0"><table style="width:100%;border-collapse:collapse;table-layout:fixed"><tr><td style="padding:9px;width:22%"><div style="font-weight:800;color:#173f31">'+discountEsc(p.category||p.name||(x.key==="__UNLINKED__"?"Unlinked invoice":"Package"))+'</div><div style="font-size:10px;color:#718078">'+discountEsc(p.name||x.key)+(isCurrent?' · current enrollment':'')+'</div></td><td style="padding:9px;white-space:nowrap;width:9%">'+discountEsc(fdt(p.start_date||(x.iv[0]&&x.iv[0].posting_date)||""))+'</td><td style="padding:9px;width:10%">'+discountEsc(p.branch||"—")+'</td><td style="padding:9px;text-align:right;font-weight:900;color:#173f31;width:10%">'+inr(x.actualPackage)+'</td><td style="padding:9px;text-align:right;color:#b45309;font-weight:900;width:10%">'+(x.hasInvoice?'−'+inr(x.discount):noInvoice)+'</td><td style="padding:9px;text-align:right;width:7%">'+(x.hasInvoice?x.pct+'%':noInvoice)+'</td><td style="padding:9px;text-align:right;font-weight:800;width:10%">'+(x.hasInvoice?inr(x.afterDiscount):noInvoice)+'</td><td style="padding:9px;text-align:right;color:#0f766e;font-weight:900;width:8%">'+(x.hasInvoice?inr(x.paid):noInvoice)+'</td><td style="padding:9px;text-align:right;color:'+(x.due?'#b42318':'#178a5f')+';font-weight:900;width:7%">'+(x.hasInvoice?inr(x.due):noInvoice)+'</td><td style="padding:9px;white-space:normal;width:12%">'+invNames+'</td></tr><tr><td colspan="10" style="padding:0 9px 10px">'+approvalBlock(x)+'</td></tr></table></td></tr>';
  }).join("")+'</tbody></table></div>':'<div style="padding:28px;text-align:center;color:#718078">No package or invoice discount records found for this client.</div>';

  body.innerHTML=summary+note+table;
 }catch(e){
  body.innerHTML='<div style="padding:28px;text-align:center"><div style="color:#a02c22;font-weight:900">Could not load package / discount details</div><div style="margin-top:6px;color:#74827a">'+discountEsc((e&&e.message)||"Unknown error")+'</div></div>';
 }
}

