 /* DUE RECOVERY FOLLOWUP — OPEN EXACT CLIENT FOLLOWUP
    ------------------------------------------------------------
    Change ONLY Enrollment Register.

    Required flow:
      Enrollment Register
        -> Due recovery followup
        -> Followup Master
        -> New followup
        -> exact client selected
        -> Pending balance (DUE) followup opened

    Do NOT leave the user on the overall Pending Dues dashboard.
 */
 if(name==="Due recovery followup"){
  if(!pid){
   toast("Patient ID is missing for this enrollment");
   return true;
  }

  const exactPid=String(pid||"").trim();
  const exactName=String(r.name||exactPid).trim();
  const exactMobile=String(r.mob||"").replace(/\D/g,"");

  /*
   * Open Followup Master in a new tab so Enrollment can keep controlling the
   * destination page until the exact client followup form is opened.
   */
  const w=window.open(
   "/followup-master?from=enrollment-register",
   "_blank"
  );

  if(!w){
   toast("Allow pop-ups to open Followup Master");
   return true;
  }

  let tries=0;
  let newViewOpened=false;
  let searchStarted=false;

  const timer=setInterval(()=>{
   tries++;

   if(!w || w.closed || tries>260){
    clearInterval(timer);

    if(tries>260){
     toast(
      "Followup Master opened, but the exact client followup could not be opened automatically."
     );
    }
    return;
   }

   try{
    const d=w.document;
    if(!d || !d.body)return;

    /*
     * STEP 1 — Open Followup Master's EXISTING "New followup" view.
     * Sidebar buttons use data-view="new".
     */
    const newNav=d.querySelector('[data-view="new"]');

    const pageTitle=String(
     (d.getElementById("lifePageTitle")||{}).textContent||""
    ).trim().toLowerCase();

    if(
     !newViewOpened &&
     newNav &&
     !newNav.classList.contains("active") &&
     !pageTitle.includes("new followup")
    ){
     try{
      newNav.click();
      newViewOpened=true;
      searchStarted=false;
     }catch(e){}
     return;
    }

    if(
     newNav &&
     (
      newNav.classList.contains("active") ||
      pageTitle.includes("new followup")
     )
    ){
     newViewOpened=true;
    }

    if(!newViewOpened)return;

    /*
     * STEP 2 — Use Followup Master's own client search.
     *
     * The live Followup Master exposes:
     *   #followupClientSearch
     *   #followupSearchResults
     * and renders exact client options with:
     *   [data-pick-follow="<Patient ID>"]
     */
    const search=d.getElementById("followupClientSearch");
    const results=d.getElementById("followupSearchResults");

    if(!search || !results)return;

    if(!searchStarted){
     searchStarted=true;

     search.focus();
     search.value=exactPid;

     search.dispatchEvent(
      new w.Event("input",{
       bubbles:true,
       cancelable:true
      })
     );

     return;
    }

    /*
     * STEP 3 — Select the exact Patient ID.
     * Never choose by mobile alone unless the Patient-ID lookup produced no
     * result. This avoids shared-family-mobile mismatches.
     */
    const options=Array.from(
     results.querySelectorAll("[data-pick-follow]")
    );

    let exactOption=options.find(btn=>
     String(
      btn.getAttribute("data-pick-follow")||""
     ).trim()===exactPid
    );

    /*
     * Fallback: exact displayed name + mobile only when Patient ID search
     * cannot produce an option.
     */
    if(!exactOption && options.length){
     exactOption=options.find(btn=>{
      const txt=String(btn.textContent||"").trim();
      const low=txt.toLowerCase();
      const digits=txt.replace(/\D/g,"");

      const sameName=
       exactName &&
       low.includes(exactName.toLowerCase());

      const sameMobile=
       exactMobile &&
       (
        digits.includes(exactMobile) ||
        digits.endsWith(exactMobile)
       );

      return sameName && (!exactMobile || sameMobile);
     });
    }

    if(exactOption){
     /*
      * Clicking the Followup Master's own result invokes its existing
      * chooseFollowupClient() function and loads:
      * - Patient details
      * - Therapy Plans
      * - Sessions
      * - Appointments
      * - Billing / pending balance
      */
     exactOption.click();

     /*
      * STEP 4 — After exact client details load, automatically select
      * "Pending balance" followup type (code DUE).
      *
      * Followup Master renders this as [data-pick-type="DUE"].
      */
     let detailTries=0;

     const detailTimer=setInterval(()=>{
      detailTries++;

      if(!w || w.closed || detailTries>160){
       clearInterval(detailTimer);
       clearInterval(timer);
       return;
      }

      try{
       const d2=w.document;

       const workspace=d2.getElementById("followupWorkspace");
       const summary=d2.getElementById("followupClientSummary");
       const dueType=d2.querySelector('[data-pick-type="DUE"]');

       const summaryText=String(
        summary&&summary.textContent||""
       ).toLowerCase();

       const clientLoaded=
        workspace &&
        !workspace.hidden &&
        (
         summaryText.includes(exactPid.toLowerCase()) ||
         (
          exactName &&
          summaryText.includes(exactName.toLowerCase())
         )
        );

       if(!clientLoaded)return;

       if(dueType && !dueType.disabled){
        try{dueType.click()}catch(e){}
       }

       /*
        * Scroll directly to the exact client's followup workspace.
        */
       try{
        workspace.scrollIntoView({
         behavior:"smooth",
         block:"start"
        });
       }catch(e){}

       try{w.focus()}catch(e){}

       clearInterval(detailTimer);
       clearInterval(timer);

       toast(
        "Due recovery followup opened for "+exactName
       );

      }catch(e){}
     },300);

     return;
    }

    /*
     * Search result may appear after the first input event. Re-fire exact ID
     * occasionally. If no Patient-ID result after several attempts, search
     * exact client name.
     */
    if(tries%12===0){
     if(options.length===0 && exactName){
      search.value=exactName;
     }else{
      search.value=exactPid;
     }

     search.dispatchEvent(
      new w.Event("input",{
       bubbles:true,
       cancelable:true
      })
     );
    }

   }catch(e){}
  },300);

  return true;
 }



 /* COLLECT PAYMENT / RECEIPT
    Open Billing V2 and show ONLY the exact Patient selected in Enrollment.
    Billing V2 exposes window.openSummary(PATIENT-ID), so we use that directly
