 /* TRANSFERS — history first, new transfer only when user chooses it.
    Existing transfer:
      -> open B2B normally
      -> switch to All Requests
      -> locate this exact client's request card
      -> show its normal All Requests detail view
      -> keep the top "New Transfer" button available for another transfer
    No existing transfer:
      -> open New Transfer and preselect this Patient.
    The B2B dashboard script itself is NOT changed. */
 if(name==="Link other branch record"||name==="Transfers"){
  const w=window.open("about:blank","_blank");
  if(!w){toast("Allow pop-ups to open Client Transfer Request");return true}

  (async()=>{
   const exactName=String(r.name||"").trim();
   const exactPid=String(pid||"").trim();
   const exactMob=String(r.mob||"").replace(/\D/g,"");

   function clean(v){return String(v==null?"":v).trim().toLowerCase()}
   function sameDigits(a,b){
    const x=String(a||"").replace(/\D/g,"");
    const y=String(b||"").replace(/\D/g,"");
    return !!(x&&y&&(x===y || (x.length>=10&&y.endsWith(x)) || (y.length>=10&&x.endsWith(y))));
   }
   function isExactRow(x){
    if(!x)return false;

    const names=[
     x.client_full_name,
     x.client_name,
     x.client
    ].map(clean).filter(Boolean);

    if(exactName && names.includes(clean(exactName)))return true;

    if(exactPid && (
     clean(x.client_id__crm_no)===clean(exactPid) ||
     clean(x.client)===clean(exactPid) ||
     clean(x.client_full_name)===clean(exactPid) ||
     clean(x.client_name)===clean(exactPid)
    ))return true;

    if(exactMob && sameDigits(x.mobile_number,exactMob))return true;

    return false;
   }

   async function queryExact(field,value){
    if(!value)return [];
    try{
     const rows=await api("frappe.client.get_list",{
      doctype:"Client Transfer Request Form",
      fields:[
       "name","client_id__crm_no","client","client_full_name","client_name",
       "mobile_number","transfer_from_branch","transfer_to_branch",
       "approval_display_status","final_approval_status",
       "date_of_transfer_request","creation","modified"
      ],
      filters:[[field,"=",value]],
      order_by:"modified desc",
      limit_start:0,
      limit_page_length:100
     });
     return (Array.isArray(rows)?rows:[]).filter(isExactRow);
    }catch(e){
     console.warn("[ENR TRANSFER CHECK]",field,e);
     return [];
    }
   }

   async function findExistingRequests(){
    const checks=[
     ["client_full_name",exactName],
     ["client_name",exactName],
     ["client",exactName],
     ["client_id__crm_no",exactPid],
     ["client",exactPid],
     ["client_full_name",exactPid],
     ["client_name",exactPid],
     ["mobile_number",r.mob||""],
     ["mobile_number",exactMob]
    ];

    const out=[];
    const seenReq=new Set();
    const seenCheck=new Set();

    for(const pair of checks){
     const checkKey=pair[0]+"|"+String(pair[1]||"");
     if(!pair[1]||seenCheck.has(checkKey))continue;
     seenCheck.add(checkKey);

     const rows=await queryExact(pair[0],pair[1]);
     rows.forEach(row=>{
      if(row&&row.name&&!seenReq.has(row.name)){
       seenReq.add(row.name);
       out.push(row);
      }
     });
    }

    out.sort((a,b)=>String(b.modified||b.creation||"").localeCompare(String(a.modified||a.creation||"")));
    return out;
   }

   function openHistoryInAllRequests(x,existingRows){
    const targetNames=new Set(existingRows.map(z=>String(z.name||"")).filter(Boolean));
    let tries=0;
    let pageAttempts=0;

    const timer=setInterval(()=>{
     tries++;

     try{
      const d=x.document;
      if(!d||!d.body){
       if(tries>140)clearInterval(timer);
       return;
      }

      /* B2B init normally opens New Transfer.
         Force All Requests after its own initialization completes. */
      if(x.B2B&&typeof x.B2B.switchMode==="function"){
       const allTab=d.getElementById("life-mode-1");
       if(!allTab||!allTab.classList.contains("active")){
        x.B2B.switchMode(1,true);
        return;
       }
      }

      const status=d.getElementById("b2b-status-filter");
      if(status&&status.value!==""){
       status.value="";
       status.dispatchEvent(new x.Event("change",{bubbles:true}));
       return;
      }

      const list=d.getElementById("b2b-all-requests-list");
      if(!list){
       if(tries>140)clearInterval(timer);
       return;
      }

      const cards=Array.from(list.querySelectorAll(".b2b-request-card"));

      /* Find this client's exact native request card on the current page. */
      let matches=cards.filter(card=>{
       const doc=String(card.getAttribute("data-docname")||"");
       return targetNames.has(doc);
      });

      if(matches.length){
       /* Keep native All Requests layout, but display only this client's cards
          on the current page. The selected card's detail opens on the right. */
       cards.forEach(card=>{
        const doc=String(card.getAttribute("data-docname")||"");
        card.style.display=targetNames.has(doc)?"":"none";
       });

       const pager=d.getElementById("b2b-request-pagination");
       if(pager)pager.style.display="none";

       const panel=d.getElementById("b2b-list-panel");
       if(panel&&!d.getElementById("enr-client-transfer-banner")){
        const banner=d.createElement("div");
        banner.id="enr-client-transfer-banner";
        banner.style.cssText="margin:12px 0;padding:12px 15px;border:1px solid #b9dec5;border-radius:8px;background:#eef8f1;color:#14532d;font-weight:800";
        banner.innerHTML=
         "Transfer history for <strong>"+String(exactName||exactPid).replace(/[&<>"]/g,s=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[s]))+
         "</strong> · To transfer this client again, click <strong>↺ New Transfer</strong> at the top.";
        panel.insertBefore(banner,panel.firstChild);
       }

       /* Native card click opens renderTransferRequestDetail() inside All Requests.
          Do NOT call openTransferRequestFromList() because that opens the wizard /
          final approval step, which is not wanted here. */
       try{matches[0].click()}catch(e){}

       clearInterval(timer);
       try{x.focus()}catch(e){}
       return;
      }

      /* The client's request may be on another native All Requests page.
         Walk forward until its exact request card is found. */
      const next=d.getElementById("b2b-next-page");
      if(next&&!next.disabled&&pageAttempts<20){
       pageAttempts++;
       next.click();
       return;
      }

      /* If we reached the end, restart from page 1 once and try again after render. */
      const prev=d.getElementById("b2b-prev-page");
      if(pageAttempts<40&&prev&&!prev.disabled){
       pageAttempts++;
       prev.click();
       return;
      }

      if(tries>140)clearInterval(timer);
     }catch(e){
      console.warn("[ENR TRANSFER HISTORY VIEW]",e);
      if(tries>140)clearInterval(timer);
     }
    },300);
   }

   try{
    const existingRows=await findExistingRequests();

    if(existingRows.length){
     /* IMPORTANT: no ?request= here.
        ?request= invokes openTransferRequestFromList() and opens the workflow
        wizard/final approval page. We want the normal All Requests screen. */
     w.location.href="/b2b-testing";

     waitForTargetWindow(
      w,
      x=>!!(x.B2B&&typeof x.B2B.switchMode==="function"),
      async x=>{
       x.B2B.switchMode(1,true);
       if(typeof x.B2B.renderAllTransferRequests==="function"){
        x.B2B.renderAllTransferRequests();
       }
       openHistoryInAllRequests(x,existingRows);
      },
      "Client Transfer Request"
     );

     toast("Transfer history opened for "+(exactName||exactPid));
    }else{
     w.location.href="/b2b-testing";

     waitForTargetWindow(
      w,
      x=>!!(x.B2B&&typeof x.B2B.selectClient==="function"),
      async x=>{
       if(typeof x.B2B.switchMode==="function")x.B2B.switchMode(0,true);
       await x.B2B.selectClient(exactPid);
      },
      "Client Transfer Request"
     );

     toast("No old transfer found — new transfer opened for "+(exactName||exactPid));
    }
   }catch(e){
    console.warn("[ENR TRANSFER ROUTING]",e);
    try{
     w.location.href="/b2b-testing";
    }catch(_){}
   }
  })();

  return true;
 }

 /* C2C / P2P — same history-first behaviour as Branch Transfer.
    Existing request -> exact All Requests detail.
    No existing request -> New Conversion Request with this client preselected. */
 if(
  name==="C2C package transfer" ||
  name==="P2P package conversion"
 ){
  const isC2C=name==="C2C package transfer";
  const route=isC2C?"/package-conversion-C2C":"/package-conversion-for-p2p";
  const doctype=isC2C
   ?"Client Package Conversion Client To Client"
   :"LIFE Client Package Conversion Same Client Package To Package";

  const w=window.open("about:blank","_blank");
  if(!w){toast("Allow pop-ups to open "+(isC2C?"C2C":"P2P"));return true}

  (async()=>{
   const exactPid=String(pid||"").trim();
   const exactName=String(r.name||"").trim();
   const exactMob=String(r.mob||"").replace(/\D/g,"");

   const norm=v=>String(v==null?"":v).trim().toLowerCase();
   const digits=v=>String(v==null?"":v).replace(/\D/g,"");
   const sameMobile=(a,b)=>{
    const x=digits(a), y=digits(b);
    return !!(x&&y&&(x===y || (x.length>=10&&y.endsWith(x)) || (y.length>=10&&x.endsWith(y))));
   };

   const fields=isC2C
    ?[
      "name","name1","client_full_name","mobile_number",
      "client_name","phone_number","transferee_full_name",
      "approval_display_status","final_approval_status",
      "conversion_status","approval_stage","creation","modified"
     ]
    :[
      "name","client_name","name1","client_full_name","mobile_number",
      "approval_display_status","final_approval_status","automation_status",
      "approval_stage","creation","modified"
     ];

   function exactMatch(row){
    if(!row)return false;

    if(isC2C){
     /* In C2C this Enrollment client is the TRANSFEROR.
        name1 is the Patient ID; client_full_name is the display name. */
     if(exactPid && (
      norm(row.name1)===norm(exactPid) ||
      norm(row.client_full_name)===norm(exactPid)
     )) return true;

     if(exactName && norm(row.client_full_name)===norm(exactName)) return true;
     if(exactMob && sameMobile(row.mobile_number,exactMob)) return true;
     return false;
    }

    /* P2P is same-client package conversion. */
    if(exactPid && (
     norm(row.client_name)===norm(exactPid) ||
     norm(row.name1)===norm(exactPid) ||
     norm(row.client_full_name)===norm(exactPid)
    )) return true;

    if(exactName && (
     norm(row.client_full_name)===norm(exactName) ||
     norm(row.client_name)===norm(exactName)
    )) return true;

    if(exactMob && sameMobile(row.mobile_number,exactMob)) return true;
    return false;
   }

   async function exactQuery(field,value){
    if(!value)return [];
    try{
     const rows=await api("frappe.client.get_list",{
      doctype,
      fields,
      filters:[[field,"=",value]],
      order_by:"modified desc",
      limit_start:0,
      limit_page_length:100
     });
     return (Array.isArray(rows)?rows:[]).filter(exactMatch);
    }catch(e){
     console.warn("[ENR "+(isC2C?"C2C":"P2P")+" CHECK]",field,e);
     return [];
    }
   }

   async function findExisting(){
    const checks=isC2C
     ?[
       ["name1",exactPid],
       ["client_full_name",exactName],
       ["mobile_number",r.mob||""],
       ["mobile_number",exactMob]
      ]
     :[
       ["client_name",exactPid],
       ["name1",exactPid],
       ["client_full_name",exactName],
       ["mobile_number",r.mob||""],
       ["mobile_number",exactMob]
      ];

    const seen=new Set(), out=[];
    for(const pair of checks){
     const key=pair[0]+"|"+String(pair[1]||"");
     if(!pair[1]||seen.has(key))continue;
     seen.add(key);
     const rows=await exactQuery(pair[0],pair[1]);
     rows.forEach(row=>{
      if(row&&row.name&&!out.some(x=>x.name===row.name))out.push(row);
     });
    }
    out.sort((a,b)=>String(b.modified||b.creation||"").localeCompare(String(a.modified||a.creation||"")));
    return out;
   }

   function selectClientInNewRequest(x){
    let tries=0;
    const timer=setInterval(()=>{
     tries++;
     if(!x||x.closed||tries>120){clearInterval(timer);return}
     try{
      const d=x.document;
      if(!d||!d.body)return;

      if(isC2C){
       const tab=d.getElementById("navTab0") || d.querySelector('.mnav[data-tab="0"]');
       if(tab&&!tab.classList.contains("on"))tab.click();

       const input=d.getElementById("transferorSearch");
       if(!input)return;

       if(input.value!==exactPid){
        input.focus();
        input.value=exactPid;
        input.dispatchEvent(new x.Event("input",{bubbles:true}));
        input.dispatchEvent(new x.Event("change",{bubbles:true}));
       }

       const items=Array.from(d.querySelectorAll("#transferorResults .c2c-api-patient-item, #transferorResults .ac-item"));
       const hit=items.find(item=>{
        const txt=norm(item.textContent);
        return (exactPid&&txt.includes(norm(exactPid))) ||
               (exactName&&txt.includes(norm(exactName))) ||
               (exactMob&&digits(item.textContent).includes(exactMob));
       });

       if(hit){
        hit.dispatchEvent(new x.MouseEvent("mousedown",{bubbles:true,cancelable:true,view:x}));
        clearInterval(timer);
        try{x.focus()}catch(e){}
       }
       return;
      }

      const tab=d.querySelector('.pkg-tab[data-tab="0"]');
      if(tab&&!tab.classList.contains("active"))tab.click();

      const input=d.getElementById("pkgClientSearch");
      if(!input)return;

      if(input.value!==exactPid){
       input.focus();
       input.value=exactPid;
       input.dispatchEvent(new x.Event("input",{bubbles:true}));
       input.dispatchEvent(new x.Event("change",{bubbles:true}));
      }

      const items=Array.from(d.querySelectorAll("#pkgClientResults .pkg-ac-item"));
      const hit=items.find(item=>{
       const data=norm(item.getAttribute("data-client"));
       const txt=norm(item.textContent);
       return (exactPid&&(data===norm(exactPid)||txt.includes(norm(exactPid)))) ||
              (exactName&&txt.includes(norm(exactName))) ||
              (exactMob&&digits(item.textContent).includes(exactMob));
      });

      if(hit){
       hit.click();
       clearInterval(timer);
       try{x.focus()}catch(e){}
      }
     }catch(e){}
    },300);
   }

   /* IMPORTANT: do not query the C2C/P2P DocType from Enrollment Register.
      The target dashboards already load the correct request fields.
      Using their own search avoids HTTP 500 from guessed/invalid fields. */
   try{
    w.location.href=route;

    let tries=0, searchApplied=false, noMatchTicks=0;
    const timer=setInterval(()=>{
     tries++;
     if(!w||w.closed||tries>160){clearInterval(timer);return}

     try{
      const d=w.document;
      if(!d||!d.body)return;

      if(isC2C){
       const allTab=d.getElementById("navTab1")||d.querySelector('.mnav[data-tab="1"]');
       if(allTab&&!allTab.classList.contains("on")){allTab.click();return}

       const search=d.getElementById("requestSearchInput");
       const list=d.getElementById("ag-list");
       if(!search||!list)return;

       if(!searchApplied){
        searchApplied=true;
        search.value=exactMob||exactPid||exactName;
        search.dispatchEvent(new w.Event("input",{bubbles:true}));
        return;
       }

       const cards=Array.from(list.querySelectorAll(".cpc-request-card"));
       if(cards.length){
        const good=cards.filter(card=>{
         const t=norm(card.textContent), ds=digits(card.textContent);
         return (exactMob&&ds.includes(exactMob))||(exactPid&&t.includes(norm(exactPid)))||(exactName&&t.includes(norm(exactName)));
        });
        cards.forEach(card=>{card.style.display=good.includes(card)?"":"none"});
        if(good.length){
         const pg=d.getElementById("requestPagination");if(pg)pg.style.display="none";
         good[0].click();
         clearInterval(timer);
         toast("C2C history opened for "+(exactName||exactPid));
         return;
        }
       }

       const lt=norm(list.textContent);
       if(lt.includes("no requests match your search")||lt.includes("no requests found")){
        noMatchTicks++;
        if(noMatchTicks>=5){clearInterval(timer);selectClientInNewRequest(w)}
       }else noMatchTicks=0;
       return;
      }

      const allTab=d.querySelector('.pkg-tab[data-tab="1"]');
      if(allTab&&!allTab.classList.contains("active")){allTab.click();return}

      const search=d.getElementById("pkgAllRequestsSearch");
      const list=d.getElementById("pkgAllRequestsList");
      if(!search||!list)return;

      if(!searchApplied){
       searchApplied=true;
       search.value=exactMob||exactPid||exactName;
       search.dispatchEvent(new w.Event("input",{bubbles:true}));
       return;
      }

      const cards=Array.from(list.querySelectorAll(".pkg-request-item"));
      if(cards.length){
       const good=cards.filter(card=>{
        const t=norm(card.textContent), ds=digits(card.textContent);
        return (exactMob&&ds.includes(exactMob))||(exactPid&&t.includes(norm(exactPid)))||(exactName&&t.includes(norm(exactName)));
       });
       cards.forEach(card=>{card.style.display=good.includes(card)?"":"none"});
       if(good.length){
        const pg=d.getElementById("pkgRequestPagination");if(pg)pg.style.display="none";
        good[0].click();
        clearInterval(timer);
        toast("P2P history opened for "+(exactName||exactPid));
        return;
       }
      }

      const lt=norm(list.textContent);
      if(lt.includes("no requests match your search")||lt.includes("no requests found")){
       noMatchTicks++;
       if(noMatchTicks>=5){clearInterval(timer);selectClientInNewRequest(w)}
      }else noMatchTicks=0;
     }catch(e){}
    },300);
   }catch(e){
    console.warn("[ENR "+(isC2C?"C2C":"P2P")+" ROUTING]",e);
    try{w.location.href=route}catch(_){}
   }
  })();

  return true;
 }

 /* WELLNESS EVALUATION SESSION — ENROLLMENT-SIDE ROUTING ONLY
    ------------------------------------------------------------
    Wellness Evaluation source is NOT modified.

    Previous problem:
    Enrollment rendered the submitted rows too early. Then the Wellness page
    finished its own init() and cleared #zs-history-results again.

    Stable flow:
      1. Open Wellness in normal browse mode.
      2. Load this exact Patient's completed Zero Sessions from ERP.
      3. Wait until the Wellness page is fully loaded.
      4. Wait a little longer for its init/branch callbacks to finish.
      5. Render submitted cards + View Details.
      6. Show Start New Evaluation below the history.
      7. Watch briefly and restore the cards if a late callback clears them.
 */
 if(name==="Wellness evaluation session"||name==="Medical tag"){
  if(!pid){
   toast("Patient ID is missing for this enrollment");
   return true;
  }

  const exactPid=String(pid||"").trim();
  const exactName=String(r.name||exactPid).trim();
  const exactMobile=String(r.mob||"").trim();
  const exactBranch=String(r.brn||r.br||"").trim();
  const exactPlan=String(plan||"").trim();

  const w=window.open(
   "/zero-session-testing?from=enrollment-register",
   "_blank"
  );

  if(!w){
   toast("Allow pop-ups to open Wellness Evaluation Session");
   return true;
  }

  Promise.resolve(
   api("frappe.client.get_list",{
    doctype:"Zero Session",
    filters:[
     ["patient","=",exactPid],
     ["status","=","Completed"]
    ],
    fields:[
     "name",
     "patient",
     "patient_name",
     "therapy_plan",
     "branch",
     "session_date",
     "status",
     "creation"
    ],
    order_by:"creation desc",
    limit_page_length:100
   })
  ).then(rows=>{
   rows=Array.isArray(rows)?rows:[];

   rows.sort((a,b)=>{
    const ae=exactPlan && String(a.therapy_plan||"").trim()===exactPlan;
    const be=exactPlan && String(b.therapy_plan||"").trim()===exactPlan;
    if(ae&&!be)return -1;
    if(!ae&&be)return 1;
    return String(b.creation||"").localeCompare(String(a.creation||""));
   });

   function esc(v){
    return String(v==null?"":v)
     .replace(/&/g,"&amp;")
     .replace(/</g,"&lt;")
     .replace(/>/g,"&gt;")
     .replace(/"/g,"&quot;")
     .replace(/'/g,"&#039;");
   }

   function maskedMobile(v){
    const digits=String(v||"").replace(/\D/g,"");
    if(digits.length<=6)return digits;
    return digits.slice(0,3)+"****"+digits.slice(-3);
   }

   function buildHistoryHtml(){
    let html="";

    if(rows.length){
     html+=rows.map(z=>{
      const clientName=
       z.patient_name||
       exactName||
       z.patient||
       "Client";

      const meta=[
       z.patient||exactPid,
       z.branch||exactBranch,
       z.session_date||""
      ].filter(Boolean).join(" • ");

      const isExact=
       exactPlan &&
       String(z.therapy_plan||"").trim()===exactPlan;

      return (
       '<div class="zs-history-item"'+
        (isExact
         ?' style="border:2px solid #1B6B3A;background:#f3fbf6"'
         :'')+
       '>'+
        '<div>'+
         '<div class="zs-history-name">'+esc(clientName)+'</div>'+
         '<div class="zs-history-meta">'+esc(meta)+'</div>'+
        '</div>'+
        '<div>'+
         '<strong>Plan</strong>'+
         '<div class="zs-history-meta">'+esc(z.therapy_plan||"-")+'</div>'+
        '</div>'+
        '<div>'+
         '<strong>Status</strong>'+
         '<div class="zs-history-meta">'+esc(z.status||"Completed")+'</div>'+
        '</div>'+
        '<div>'+
         '<button type="button" class="btn btn-n zs-view-details" '+
          'data-zero-session="'+esc(z.name)+'" style="padding:7px 12px">'+
          'View Details'+
         '</button>'+
        '</div>'+
       '</div>'
      );
     }).join("");
    }else{
     html+=
      '<div class="zs-history-empty">'+
       'No completed Wellness Evaluation Session found for this client.'+
      '</div>';
    }

    if(exactPlan){
     html+=
      '<div id="life-enr-new-wellness-card" '+
       'style="margin-top:12px;padding:12px;border:1px dashed #86b99a;'+
       'border-radius:9px;background:#f8fcf9;display:flex;align-items:center;'+
       'justify-content:space-between;gap:12px;flex-wrap:wrap">'+
       '<div>'+
        '<div style="font-weight:800;color:#14532D">New Wellness Evaluation</div>'+
        '<div class="zs-history-meta">Selected Therapy Plan: '+esc(exactPlan)+'</div>'+
       '</div>'+
       '<button type="button" id="life-enr-start-new-wellness" '+
        'style="border:0;border-radius:8px;background:#1B6B3A;color:#fff;'+
        'font-weight:800;padding:9px 14px;cursor:pointer">'+
        '＋ Start New Evaluation'+
       '</button>'+
      '</div>';
    }

    return html;
   }

   function renderIntoWellness(){
    if(!w || w.closed)return false;

    try{
     const d=w.document;
     if(!d || !d.body)return false;

     const input=d.getElementById("zs-history-search");
     const box=d.getElementById("zs-history-results");
     const hint=d.getElementById("zs-search-hint");

     if(!input || !box || !hint)return false;

     const stepBar=d.querySelector(".step-bar");
     if(stepBar)stepBar.style.display="none";

     for(let i=1;i<=10;i++){
      const wp=d.getElementById("wp-"+i);
      if(wp)wp.classList.remove("on");
     }

     input.value=
      exactName+
      (exactMobile ? " — "+maskedMobile(exactMobile) : "");

     input.title="";

     const shell=input.closest(".zs-search-shell");
     if(shell){
      if(exactMobile){
       shell.setAttribute(
        "data-full-mobile",
        "Full mobile: "+exactMobile
       );
      }else{
       shell.removeAttribute("data-full-mobile");
      }
     }

     const dd=d.getElementById("zs-client-dropdown");
     if(dd){
      dd.classList.remove("show");
      dd.innerHTML="";
     }

     box.innerHTML=buildHistoryHtml();
     box.classList.add("show");
     box.style.display="block";

     if(rows.length){
      hint.textContent=
       "Submitted Wellness Evaluation found. Use View Details to review it, "+
       "or Start New Evaluation below.";
     }else{
      hint.textContent=
       "No submitted Wellness Evaluation found. Start a new evaluation below.";
     }

     const newBtn=d.getElementById("life-enr-start-new-wellness");
     if(newBtn && !newBtn.dataset.lifeBound){
      newBtn.dataset.lifeBound="1";
      newBtn.addEventListener("click",()=>{
       const newUrl=
        "/zero-session-testing?therapy_plan="+encodeURIComponent(exactPlan)+
        "&patient="+encodeURIComponent(exactPid)+
        "&from=enrollment-register&mode=new";

       w.location.href=newUrl;
      });
     }

     return true;
    }catch(e){
     console.warn("[ENR WELLNESS RENDER]",e);
     return false;
    }
   }

   let tries=0;

   const readyTimer=setInterval(()=>{
    tries++;

    if(!w || w.closed || tries>180){
     clearInterval(readyTimer);

     if(tries>180){
      toast(
       "Wellness page opened, but history could not be displayed automatically."
      );
     }
     return;
    }

    try{
     const d=w.document;
     const input=d&&d.getElementById("zs-history-search");
     const box=d&&d.getElementById("zs-history-results");

     if(
      !d ||
      !input ||
      !box ||
      (d.readyState!=="interactive" && d.readyState!=="complete")
     ){
      return;
     }

     clearInterval(readyTimer);

     /*
      * Important: wait for Wellness init() to finish before rendering.
      */
     setTimeout(()=>{
      const ok=renderIntoWellness();

      if(!ok){
       toast("Wellness page loaded, but history rendering failed.");
       return;
      }

      /*
       * A few async callbacks in Wellness can still finish after init.
       * Keep the selected history visible if one of them clears the box.
       */
      let watchCount=0;
      const watch=setInterval(()=>{
       watchCount++;

       if(!w || w.closed || watchCount>24){
        clearInterval(watch);
        return;
       }

       try{
        const d=w.document;
        const box=d.getElementById("zs-history-results");

        if(
         box &&
         !box.querySelector(".zs-history-item") &&
         !box.querySelector("#life-enr-new-wellness-card")
        ){
         renderIntoWellness();
        }
       }catch(e){}

       if(watchCount>=24){
        clearInterval(watch);
       }
      },300);

      try{w.focus()}catch(e){}

      toast(
       "Wellness Evaluation opened for "+exactName+
       " — submitted history and new evaluation are shown"
      );

     },1600);

    }catch(e){}

   },250);

  }).catch(err=>{
   console.warn("[ENR WELLNESS HISTORY LOAD]",err);

   if(exactPlan){
    try{
     w.location.href=
      "/zero-session-testing?therapy_plan="+encodeURIComponent(exactPlan)+
      "&patient="+encodeURIComponent(exactPid)+
      "&from=enrollment-register&mode=new";
    }catch(e){}
   }
  });

  return true;
 }

 return false;
}

/* Generic client picker for other LIFE dashboards. */
function focusOnlySelectedClient(w,r,it){
 let tries=0,lastInput=null,lastValue="";
 const wanted=String(r.pid||r.mob||r.name||"").trim();
 if(!wanted)return;
 const timer=setInterval(()=>{
  tries++;
  if(!w||w.closed||tries>100){clearInterval(timer);return}
  try{
   const d=w.document;if(!d||!d.body)return;

   if(it[0]==="Followup note"){
    const nb=d.querySelector('[data-view="new"]');
    if(nb&&!nb.classList.contains("active"))nb.click();
    const fi=d.getElementById("followupClientSearch");
    if(fi){
     if(fi.value!==String(r.pid||r.name||""))fireTargetInput(w,fi,String(r.pid||r.name||""));
     if(clickExactTargetMatch(w,d,r)){clearInterval(timer);try{w.focus()}catch(e){};return}
    }
    return;
   }

   const inputs=Array.from(d.querySelectorAll('input:not([type="hidden"]),textarea')).filter(el=>{
    try{return el.offsetParent!==null&&!el.disabled&&!el.readOnly}catch(e){return false}
   }).sort((a,b)=>targetInputScore(b)-targetInputScore(a));
   const input=inputs.find(el=>targetInputScore(el)>20);
   if(input){
    if(lastInput!==input||lastValue!==wanted||tries%6===0){
     fireTargetInput(w,input,wanted);lastInput=input;lastValue=wanted;
    }
    if(clickExactTargetMatch(w,d,r)){clearInterval(timer);try{w.focus()}catch(e){};return}
   }

   const sels=Array.from(d.querySelectorAll("select")).filter(el=>
    /client|patient/.test([el.id,el.name,el.getAttribute("aria-label")].join(" ").toLowerCase())
   );
   for(const sel of sels){
    const opt=Array.from(sel.options||[]).find(o=>
     clientNeedles(r).some(n=>n&&((o.value||"")+" "+(o.textContent||"")).toLowerCase().includes(n.toLowerCase()))
    );
    if(opt){
     sel.value=opt.value;
     sel.dispatchEvent(new w.Event("change",{bubbles:true}));
     clearInterval(timer);
     try{w.focus()}catch(e){}
     return;
    }
   }
  }catch(e){}
 },450);
}

/* ═══════════ FAMILY LINK POPUP ═══════════
