   Child DocType: Client Family Member
   =============================================================== */
let FAMILY_LINK_STATE={rowId:"",patient:"",clientName:"",selected:null,doc:null,seq:0};

function familyEsc(v){
 return String(v==null?"":v)
  .replace(/&/g,"&amp;")
  .replace(/</g,"&lt;")
  .replace(/>/g,"&gt;")
  .replace(/\"/g,"&quot;")
