function familyMobileHover(n){
 const x=dig(n);
 if(!x)return "—";
 const masked=(x.length>=10)?x.slice(0,3)+"XXXX"+x.slice(-3):x;
 return '<span class="mobhover" title="Hover to view full number" '+
  'data-full="'+familyEsc(x)+'" data-mask="'+familyEsc(masked)+'" '+
  'style="cursor:pointer;text-decoration:underline dotted;text-underline-offset:2px" '+
  'onmouseenter="this.textContent=this.dataset.full" '+
  'onmouseleave="this.textContent=this.dataset.mask">'+familyEsc(masked)+'</span>';
}

function familyRenderExisting(){
