async function familyLinkSearchInput(){
 const inp=document.getElementById("familyClientSearch"),box=document.getElementById("familyClientResults");
 if(!inp||!box)return;
 const q=inp.value.trim();
 FAMILY_LINK_STATE.selected=null;
