 if(q.length<3){box.style.display="none";box.innerHTML="";return}
 const seq=++FAMILY_LINK_STATE.seq;
 box.style.display="block";box.innerHTML='<div style="padding:11px;color:#748078">Searching clients…</div>';
 const rows=await searchPatientsEverywhere(q);
 if(seq!==FAMILY_LINK_STATE.seq)return;
 const filtered=(rows||[]).filter(x=>String(x.name||"")!==String(FAMILY_LINK_STATE.patient||""));
 if(!filtered.length){box.innerHTML='<div style="padding:11px;color:#748078">No matching client found</div>';return}
 box.innerHTML=filtered.map(function(x){
  const pid=String(x.name||""),nm=String(x.patient_name||pid),mob=dig(x.mobile||x.phone||"");
  const a=pid.replace(/\\/g,"\\\\").replace(/'/g,"\\'");
  const b=nm.replace(/\\/g,"\\\\").replace(/'/g,"\\'");
  const c=mob.replace(/\\/g,"\\\\").replace(/'/g,"\\'");
  return '<button type="button" onclick="selectFamilyLinkClient(\''+a+'\',\''+b+'\',\''+c+'\')" style="width:100%;border:0;border-bottom:1px solid #edf2ef;background:#fff;padding:10px 12px;text-align:left;cursor:pointer"><b style="display:block;color:#123d2b;font-size:12.5px">'+familyEsc(nm)+'</b><span style="display:block;margin-top:2px;color:#748078;font-size:11px">'+familyEsc(pid)+(mob?" · "+familyMobileHover(mob):"")+'</span></button>';
 }).join("");
