async function saveFamilyLink(){
 const er=document.getElementById("familyLinkError"),btn=document.getElementById("familyLinkSaveBtn");
 if(er){er.style.display="none";er.textContent=""}
 try{
  const selected=FAMILY_LINK_STATE.selected;
  const relation=(document.getElementById("familyRelation")||{}).value||"";
  if(!selected||!selected.patient)throw new Error("Select a family member/client.");
  if(!relation)throw new Error("Select the relation.");
  if(selected.patient===FAMILY_LINK_STATE.patient)throw new Error("A client cannot be linked to the same client record.");
  if(btn){btn.disabled=true;btn.textContent="Saving…"}
  const doc=await api("frappe.client.get",{doctype:"Patient",name:FAMILY_LINK_STATE.patient});
  if(!doc || !Object.prototype.hasOwnProperty.call(doc,"custom_family_members"))throw new Error("Patient field custom_family_members is not installed.");
  const rows=Array.isArray(doc.custom_family_members)?doc.custom_family_members:[];
  if(rows.some(x=>String(x.linked_client||"")===String(selected.patient||"")))throw new Error(selected.name+" is already linked as a family member.");
  rows.push({doctype:"Client Family Member",linked_client:selected.patient,linked_client_name:selected.name||selected.patient,linked_mobile:selected.mobile||"",relation:relation,linked_on:new Date().toISOString().slice(0,19).replace("T"," "),linked_by:(window.frappe&&frappe.session&&frappe.session.user)||""});
  doc.custom_family_members=rows;
  const saved=await api("frappe.client.save",{doc:doc});
  FAMILY_LINK_STATE.doc=saved||doc;
  familyRenderExisting();
  FAMILY_LINK_STATE.selected=null;
  const inp=document.getElementById("familyClientSearch");if(inp)inp.value="";
  const rel=document.getElementById("familyRelation");if(rel)rel.value="";
  const sel=document.getElementById("familySelectedClient");if(sel)sel.style.display="none";
  toast("Family member linked to "+FAMILY_LINK_STATE.clientName);
 }catch(e){if(er){er.style.display="block";er.textContent=(e&&e.message)||"Unable to save family link"}}
 finally{if(btn){btn.disabled=false;btn.textContent="👪 Save family link"}}
}


