async function loadClientRecordDirect(patient){
 const doc=await api("frappe.client.get",{
  doctype:"Patient",
  name:patient
 });

 if(!doc)throw new Error("Client/Patient not found.");

 const rows=Array.isArray(doc.custom_record_book_numbers)
  ?doc.custom_record_book_numbers
  :[];

 return {
  ok:1,
  patient:patient,
  patient_name:doc.patient_name||doc.first_name||patient,
  branch:doc.custom_branch||doc.branch_name||"",
  records:rows.map(x=>({
   name:x.name||"",
   record_book_number:String(x.record_book_number||"").trim().toUpperCase(),
   record_book_date:x.record_book_date||"",
   serial_reference:x.serial_reference||"",
   remarks:x.remarks||"",
   added_by:x.added_by||"",
   creation:x.creation||""
  })),
  available_serials:[]
 };
}

