async function checkRecordBookDuplicate(number,currentPatient){
 number=String(number||"").trim().toUpperCase();

 if(!number)return [];

 /* First check the current popup/client data immediately. */
 const currentRecords=
  CLIENT_RECORD_STATE &&
  CLIENT_RECORD_STATE.payload &&
  Array.isArray(CLIENT_RECORD_STATE.payload.records)
   ?CLIENT_RECORD_STATE.payload.records
   :[];

 const sameClient=currentRecords.find(x=>
  String(x.record_book_number||"").trim().toUpperCase()===number
 );

 if(sameClient){
  throw new Error(
   "Record Book Number "+number+
   " is already registered for this client ("+
   String(currentPatient||"")+
   "). Please enter a different Record Book Number."
  );
 }

 try{
  const rows=await api("frappe.client.get_list",{
   doctype:"Client Record Book Number",
   fields:["name","parent","record_book_number"],
   filters:[
    ["record_book_number","=",number]
   ],
   limit_start:0,
   limit_page_length:50
  });

  const list=Array.isArray(rows)?rows:[];

  if(list.length){
   const hit=list[0];
   const owner=String(hit.parent||"").trim();

   if(owner===String(currentPatient||"").trim()){
    throw new Error(
     "Record Book Number "+number+
     " is already registered for this client ("+
     owner+
     "). Please enter a different Record Book Number."
    );
   }

   throw new Error(
    "Record Book Number "+number+
    " is already registered to another client"+
    (owner?" ("+owner+")":"")+
    ". This number cannot be used again."
   );
  }

  return [];

 }catch(e){
  const msg=String((e&&e.message)||"");

  /* Duplicate errors must never be ignored. */
  if(
   /already registered/i.test(msg) ||
   /cannot be used again/i.test(msg) ||
   /already used/i.test(msg)
  ){
   throw e;
  }

  /* If direct child-table query is permission blocked,
     Patient Before Save validation remains the final backend protection. */
  console.warn("[ENR RECORD DUPLICATE PRECHECK]",e);
  return [];
 }
}

async function saveRecordBookDirect(number,remarks){
 const patient=CLIENT_RECORD_STATE.patient;

 await checkRecordBookDuplicate(number,patient);

 const doc=await api("frappe.client.get",{
  doctype:"Patient",
  name:patient
 });

 if(!doc)throw new Error("Client/Patient not found.");

 if(!Array.isArray(doc.custom_record_book_numbers)){
  doc.custom_record_book_numbers=[];
 }

 const ownDuplicate=doc.custom_record_book_numbers.some(x=>
  String(x.record_book_number||"").trim().toUpperCase()===number
 );

 if(ownDuplicate){
  throw new Error(
   "Record Book Number "+number+" is already registered for this client."
  );
 }

 doc.custom_record_book_numbers.push({
  doctype:"Client Record Book Number",
  record_book_number:number,
  record_book_date:new Date().toISOString().slice(0,10),
  remarks:remarks||"",
  added_by:(window.frappe&&frappe.session&&frappe.session.user)||""
 });

 const saved=await api("frappe.client.save",{doc:doc});

 const rows=
  saved && Array.isArray(saved.custom_record_book_numbers)
   ?saved.custom_record_book_numbers
   :doc.custom_record_book_numbers;

 return {
  ok:1,
  patient:patient,
  records:rows.map(x=>({
   name:x.name||"",
   record_book_number:String(x.record_book_number||"").trim().toUpperCase(),
   record_book_date:x.record_book_date||"",
   serial_reference:x.serial_reference||"",
   remarks:x.remarks||"",
   added_by:x.added_by||"",
   creation:x.creation||""
  })),
  available_serials:[],
  message:"Record Book "+number+" registered successfully."
 };
}

async function assignClientRecordBook(){
 const btn=document.getElementById("clientRecordSaveBtn");
 const er=document.getElementById("clientRecordError");

 if(er){
  er.style.display="none";
  er.textContent="";
 }

 try{
  const manual=String(
   (document.getElementById("clientRecordManualNumber")||{}).value||""
  ).trim().toUpperCase();

  const selected=String(
   (document.getElementById("clientRecordSerial")||{}).value||""
  ).trim().toUpperCase();

  const number=manual||selected;

  const remarks=String(
   (document.getElementById("clientRecordRemarks")||{}).value||""
  ).trim();

  if(!number){
   throw new Error("Enter the Record Book Number.");
  }

  if(btn){
   btn.disabled=true;
   btn.textContent="Registering…";
  }

  /* STRICT GLOBAL UNIQUE CHECK:
     do not even call the assign API when this number already exists. */
  await checkRecordBookDuplicate(
   number,
   CLIENT_RECORD_STATE.patient
  );

  let result=null;

  /* First use the controlled Stores API when it is working. */
  try{
   const p=await api("life_client_record_book_api",{
    action:"assign",
    patient:CLIENT_RECORD_STATE.patient,
    record_book_number:number,
    remarks:remarks
   });

   if(p&&p.ok){
    result=p;
   }else if(p){
    throw new Error(p.message||"Unable to register Record Book Number.");
   }
  }catch(apiError){
   console.warn("[ENR RECORD BOOK ASSIGN API]",apiError);

   const apiMsg=String((apiError&&apiError.message)||"");

   /* Never bypass duplicate-number errors through the manual fallback. */
   if(
    /already registered/i.test(apiMsg) ||
    /already assigned/i.test(apiMsg) ||
    /already used/i.test(apiMsg) ||
    /cannot be reused/i.test(apiMsg) ||
    /cannot be used again/i.test(apiMsg)
   ){
    throw apiError;
   }

   /* Only genuine API/server failures use the direct Patient fallback. */
   result=await saveRecordBookDirect(number,remarks);
  }

  if(!result||!result.ok){
   throw new Error(
    (result&&result.message)||
    "Unable to register Record Book Number."
   );
  }

  toast(
   result.message||
   ("Record Book "+number+" registered successfully.")
  );

  let fresh=result;

  try{
   fresh=await loadClientRecordDirect(
    CLIENT_RECORD_STATE.patient
   );
  }catch(e){}

  CLIENT_RECORD_STATE.payload=fresh;

  const r=DATA.find(
   x=>x.id===CLIENT_RECORD_STATE.rowId
  );

  if(
   r &&
   fresh &&
   fresh.records &&
   fresh.records.length
  ){
   r.card=
    fresh.records[0].record_book_number||
    r.card;
   render();
  }

  renderClientRecordPopup(fresh,false);

 }catch(e){
  const msg=
   (e&&e.message)||
   "Unable to register Record Book Number.";

  if(er){
   er.style.display="block";
   er.textContent=msg;
  }

  if(
   /already registered/i.test(msg) ||
   /already assigned/i.test(msg) ||
   /already used/i.test(msg) ||
   /cannot be reused/i.test(msg) ||
   /cannot be used again/i.test(msg)
  ){
   showRecordBookErrorPopup(msg);

   const inp=document.getElementById("clientRecordManualNumber");
   if(inp){
    inp.focus();
    inp.select();
   }
  }
 }finally{
  if(btn){
   btn.disabled=false;
   btn.textContent="📘 Register Record Book Number";
  }
 }
}



