async function saveMiniRecord(){
 const btn=document.getElementById("miniRecordSaveBtn");
 const err=document.getElementById("miniRecordError");

 if(err){
  err.style.display="none";
  err.textContent="";
 }

 try{
  const number=String(
   (document.getElementById("miniRecordNumber")||{}).value||""
  ).trim();

  const date=String(
   (document.getElementById("miniRecordDate")||{}).value||""
  ).trim();

  const remarks=String(
   (document.getElementById("miniRecordRemarks")||{}).value||""
  ).trim();

  if(!number){
   throw new Error("Enter the Mini Record Number.");
  }

  if(btn){
   btn.disabled=true;
   btn.textContent="Saving…";
  }

  const doc=await api("frappe.client.get",{
   doctype:"Patient",
   name:MINI_RECORD_STATE.patient
  });

  if(!doc){
   throw new Error("Client/Patient not found.");
  }

  if(!Array.isArray(doc.custom_mini_record_numbers)){
   doc.custom_mini_record_numbers=[];
  }

  const duplicate=doc.custom_mini_record_numbers.some(x=>
   String(x.mini_record_number||"").trim().toLowerCase()===
   number.toLowerCase()
  );

  if(duplicate){
   throw new Error(
    "Mini Record Number "+number+
    " is already registered for this client."
   );
  }

  doc.custom_mini_record_numbers.push({
   doctype:"Client Mini Record Number",
   mini_record_number:number,
   mini_record_date:date||miniRecordToday(),
   remarks:remarks,
   added_by:
    (window.frappe&&frappe.session&&frappe.session.user)||
    ""
  });

  const saved=await api("frappe.client.save",{
   doc:doc
  });

  const rows=
   saved &&
   Array.isArray(saved.custom_mini_record_numbers)
    ?saved.custom_mini_record_numbers
    :doc.custom_mini_record_numbers;

  MINI_RECORD_STATE.records=rows.map(x=>({
   name:x.name||"",
   mini_record_number:String(x.mini_record_number||"").trim(),
   mini_record_date:x.mini_record_date||"",
   remarks:x.remarks||"",
   added_by:x.added_by||""
  }));

  toast(
   "Mini Record "+number+" saved for "+
   MINI_RECORD_STATE.clientName
  );

  renderMiniRecordPopup(
   MINI_RECORD_STATE.records
  );

 }catch(e){
  if(err){
   err.style.display="block";
   err.textContent=
    (e&&e.message)||
    "Unable to save Mini Record.";
  }
 }finally{
  if(btn){
   btn.disabled=false;
   btn.textContent="📒 Add Mini Record";
  }
 }
}



/* ═══════════ SEND MESSAGE — EXACT CLIENT FOLLOWUP ═══════════
   Enrollment Register -> Send message
   Opens Followup Master -> New followup -> exact client -> Existing Client
   and selects WhatsApp channel. It must not stop on the dashboard.
*/
function openSendMessageForClient(r){
 const pid=String(r&&r.pid||"").trim();
 const exactName=String(r&&r.name||pid).trim();
 const exactMobile=String(r&&r.mob||"").replace(/\D/g,"");

 if(!pid){
  toast("Patient ID is missing for this enrollment");
  return;
 }

 const w=window.open(
  "/followup-master?from=enrollment-register",
  "_blank"
 );

 if(!w){
  toast("Allow pop-ups to open Followup Master");
  return;
 }

 let tries=0;
 let newViewOpened=false;
 let searchStarted=false;
 let clientPicked=false;

 const timer=setInterval(()=>{
  tries++;

  if(!w || w.closed || tries>300){
   clearInterval(timer);

   if(tries>300){
    toast(
     "Followup Master opened, but the exact client message form could not be opened automatically."
    );
   }

   return;
  }

  try{
   const d=w.document;
   if(!d || !d.body)return;

   const root=d.getElementById("lifeHealthcareApp");
   const loading=d.getElementById("lifeLoading");

   if(!root)return;

   const loadingDone=
    !loading ||
    loading.style.display==="none" ||
    w.getComputedStyle(loading).display==="none";

   if(!loadingDone)return;

   /* 1. Open New followup */
   const newNav=root.querySelector('[data-view="new"]');

   const pageTitle=String(
    (d.getElementById("lifePageTitle")||{}).textContent||""
   ).trim().toLowerCase();

   if(
    !newViewOpened &&
    newNav &&
    !newNav.classList.contains("active") &&
    !pageTitle.includes("new followup")
   ){
    try{newNav.click()}catch(e){}
    newViewOpened=true;
    searchStarted=false;
    return;
   }

   if(
    newNav &&
    (
     newNav.classList.contains("active") ||
     pageTitle.includes("new followup")
    )
   ){
    newViewOpened=true;
   }

   if(!newViewOpened)return;

   /* 2. Search exact Patient ID */
   const search=d.getElementById("followupClientSearch");
   const results=d.getElementById("followupSearchResults");

   if(!search || !results)return;

   if(!searchStarted && !clientPicked){
    searchStarted=true;
    search.focus();
    search.value=pid;

    search.dispatchEvent(
     new w.Event("input",{
      bubbles:true,
      cancelable:true
     })
    );

    return;
   }

   /* 3. Select exact client */
   if(!clientPicked){
    const options=Array.from(
     results.querySelectorAll("[data-pick-follow]")
    );

    let exactOption=options.find(btn=>
     String(
      btn.getAttribute("data-pick-follow")||""
     ).trim()===pid
    );

    if(!exactOption && options.length && exactName){
     exactOption=options.find(btn=>{
      const txt=String(btn.textContent||"").trim();
      const low=txt.toLowerCase();
      const digits=txt.replace(/\D/g,"");

      const sameName=
       low.includes(exactName.toLowerCase());

      const sameMobile=
       !exactMobile ||
       digits.includes(exactMobile) ||
       digits.endsWith(exactMobile);

      return sameName && sameMobile;
     });
    }

    if(exactOption){
     clientPicked=true;
     try{exactOption.click()}catch(e){}
     return;
    }

    /* async search retry */
    if(tries%10===0){
     search.value=pid;
     search.dispatchEvent(
      new w.Event("input",{
       bubbles:true,
       cancelable:true
      })
     );
    }

    return;
   }

   /* 4. Confirm exact selected client */
   const workspace=d.getElementById("followupWorkspace");
   const summary=d.getElementById("followupClientSummary");

   if(!workspace || workspace.hidden || !summary)return;

   const summaryText=String(
    summary.textContent||""
   ).toLowerCase();

   const exactClientLoaded=
    summaryText.includes(pid.toLowerCase()) ||
    (
     exactName &&
     summaryText.includes(exactName.toLowerCase())
    );

   if(!exactClientLoaded)return;

   /* 5. Existing Client followup */
   const existingType=root.querySelector(
    '[data-pick-type="EXI"]'
   );

   if(existingType && !existingType.disabled){
    const title=String(
     (d.getElementById("followupPanelTitle")||{}).textContent||""
    ).toLowerCase();

    const typeAlreadySelected=
     existingType.classList.contains("active") ||
     title.includes("existing");

    if(!typeAlreadySelected){
     try{existingType.click()}catch(e){}
     return;
    }
   }

   /* 6. Set WhatsApp as the message channel */
   const whatsapp=d.querySelector(
    'input[name="lifeChannel"][value="WhatsApp"]'
   );

   if(whatsapp && !whatsapp.checked){
    whatsapp.checked=true;
    whatsapp.dispatchEvent(
     new w.Event("change",{bubbles:true})
    );
   }

   const common=d.getElementById("followupCommon");
   if(!common || common.hidden)return;

   clearInterval(timer);

   /* Put cursor directly in the message/followup remarks field */
   const remarks=d.getElementById("followupRemarks");

   if(remarks){
    try{
     remarks.scrollIntoView({
      behavior:"smooth",
      block:"center"
     });
     remarks.focus();
    }catch(e){}
   }else{
    try{
     workspace.scrollIntoView({
      behavior:"smooth",
      block:"start"
     });
    }catch(e){}
   }

   try{w.focus()}catch(e){}

   toast(
    "Send message opened for "+exactName
   );

  }catch(e){}
 },300);
}


