async function getOtherBranchTransferRows(patientId,clientName){
 const fieldSets=[
  [
   "name","docstatus","client_full_name","client","client_id__crm_no",
   "transfer_from_branch","transfer_to_branch",
   "approval_display_status","final_approval_status",
   "date_of_transfer_request","remarks","creation","modified"
  ],
  [
   "name","docstatus","client_full_name","client",
   "transfer_from_branch","transfer_to_branch",
   "approval_display_status","final_approval_status",
   "remarks","creation","modified"
  ]
 ];

 const filtersToTry=[
  ["client_full_name","=",patientId],
  ["client","=",patientId],
  ["client_id__crm_no","=",patientId]
 ];

 if(clientName){
  filtersToTry.push(["client_full_name","=",clientName]);
  filtersToTry.push(["client","=",clientName]);
 }

 const out=[];
 const seen=new Set();

 for(const fields of fieldSets){
  for(const filter of filtersToTry){
   try{
    const rows=await api("frappe.client.get_list",{
     doctype:"Client Transfer Request Form",
     filters:[filter],
     fields:fields,
     order_by:"modified desc",
     limit_page_length:500
    });

    (Array.isArray(rows)?rows:[]).forEach(row=>{
     if(!row || !row.name || seen.has(row.name))return;
     seen.add(row.name);
     out.push(row);
    });
   }catch(e){}
  }

  if(out.length)break;
 }

 return out;
}

