:11px"></div><div style="display:flex;justify-content:flex-end;gap:9px;margin-top:14px"><button type="button" onclick="closeSendMessagePopup()" style="border:1px solid #cad9d1;background:#fff;color:#314d40;border-radius:9px;padding:9px 14px;font-weight:800;cursor:pointer">Cancel</button><button type="button" onclick="sendEnrollmentWhatsappMessage()" style="border:1px solid #0f7b50;background:#0f7b50;color:#fff;border-radius:9px;padding:9px 14px;font-weight:850;cursor:pointer">Open WhatsApp</button></div></div></div>`;
