function closeSendMessagePopup(){const ov=document.getElementById("lifeSendMessageOv");if(ov)ov.style.display="none";}
function openSendMessagePopup(id){const r=DATA.find(x=>x.id===id);if(!r){toast("Enrollment record not found");return}const pid=String(r.pid||"").trim(),name=String(r.name||pid||"Client").trim(),mobile=String(r.mob||r.alt||"").trim();SEND_MESSAGE_STATE={rowId:id,patient:pid,clientName:name,mobile};const ov=ensureSendMessagePopup();ov.querySelector("#sendMessageTitle").textContent=name+" — Send Message";ov.querySelector("#sendMessageSub").textContent=pid||"Selected client";ov.querySelector("#sendMessageClient").textContent=name;ov.querySelector("#sendMessageMobile").textContent=mobile||"No mobile number";const txt=ov.querySelector("#sendMessageText"),err=ov.querySelector("#sendMessageError");txt.value="";err.style.display="none";err.textContent="";ov.style.display="block";setTimeout(()=>txt.focus(),30);}
