function doAct(sel,id){
 if(!sel.value)return;
 const [g,i]=sel.value.split("|");
 const grp=ACTIONS.find(x=>x.g===g);
 if(!grp||!grp.items[+i])return;
 const it=grp.items[+i];
 const r=DATA.find(x=>x.id===id);
 if(!r)return;

 const ctx={
  source:"enrollment-register",
  action:it[0],
  client:r.pid||"",
  patient:r.pid||"",
  client_name:r.name||"",
  mobile:r.mob||"",
  alt_mobile:r.alt||"",
  therapy_plan:r.plan||r.id||"",
  branch:r.brn||r.br||"",
  enrolled:r.enrolled||"",
  start:r.start||"",
  saved_at:new Date().toISOString()
 };
 try{sessionStorage.setItem("life_action_context",JSON.stringify(ctx))}catch(e){}

 /* Send message opens directly from Enrollment Register — no Followup Master. */
 if(it[0]==="Send message"){
  openSendMessagePopup(id);
  return;
 }


 /* Link other branch record stays inside Enrollment Register. */
 if(it[0]==="Link other branch record"){
  openOtherBranchRecordPopup(id);
  return;
 }



 /* Assign Mini Record stays inside Enrollment Register. */
 if(it[0]==="Assign mini record"){
  openMiniRecordPopup(id);
  return;
 }

 /* Assign Record opens inside Enrollment Register. */
 if(it[0]==="Assign record"){openClientRecordPopup(id);return;}

 /* Family linking is handled inside Enrollment Register. */
 if(it[0]==="Link family member"){
  openFamilyLinkPopup(id);
  return;
 }

 /* Use exact dashboard APIs first. */
 if(openKnownClientDashboard(it,r))return;

 /* Remaining dashboards get URL context plus deterministic client search. */
 const url=actionUrl(it,r);
 const w=window.open(url,"_blank");
 if(!w){toast("Allow pop-ups to open "+it[0]);return}
 focusOnlySelectedClient(w,r,it);
 toast(it[0]+" opened for "+r.name);
}

/* ═══════════ CLIENT 360 ═══════════ */
function mk(n){
 const x=dig(n);
 if(!x)return "—";
 return (MASK&&x.length>=10)?x.slice(0,3)+"XXXX"+x.slice(-3):x;
}
function mobHover(n){
 const x=dig(n);
 if(!x)return "—";
 const masked=mk(x);
 return `<span class="mobhover" data-full="${x}" data-mask="${masked}" onmouseenter="this.textContent=this.dataset.full" onmouseleave="this.textContent=this.dataset.mask">${masked}</span>`;
}
function stsB(r){const m={Active:"b-ok",Break:"b-wa",Deactivated:"b-cr",Completed:"b-in"};return `<span class="bdg ${m[r.status]}">${r.status}</span>`}
function regB(r){return `<span class="bdg ${r.reg==="Regular"?"b-in":"b-or"}">${r.reg}</span>`}
function KV(k,v,c){return `<div class="kvi ${c||""}"><div class="k">${k}</div><div class="v">${v}</div></div>`}
function TT(t,sh){return `<div class="mtitle">${t}${sh?`<span class="sh">${sh}</span>`:""}</div>`}
function gapD(d){if(!d)return NaN;return Math.round((new Date(TODAY)-new Date(d))/864e5)}

/* ── flag bar — only what must be noticed ── */
function flagBar(r){
 const F=fin(r), t=tierOf(r), o=[];
 if(r.nj)o.push(`<span class="flg gold big">🟡 New joined · ${fdt(r.enrolled)}</span>`);
 if(r.status==="Completed")o.push(`<span class="flg g big">✔ Treatment completed</span>`);
 if(r.isSlim&&r.wl!=null)o.push(`<span class="flg ${r.wl>0?"g":"a"}">⚖️ ${r.wl>0?"−"+r.wl+" kg lost":r.wl<0?"+"+Math.abs(r.wl)+" kg gained":"no weight change"}</span>`);
 if(r.nobill)o.push(`<span class="flg a">🧾 No invoice linked</span>`);
 if(t)o.push(`<span class="flg gold big">👑 ${t}</span>`);
 const od=r.nextDue&&r.nextDue<TODAY&&r.due>0;
 if(r.due>0)o.push(`<span class="flg ${od?"r":"a"} big">${od?"🔴 OVERDUE":"💰 Due"} ${inr(r.due)}${od?" · "+fdt(r.nextDue):""}</span>`);
 else o.push(`<span class="flg g">✅ Fully paid</span>`);
 if(F.ahead>0)o.push(`<span class="flg r">⚠️ ${inr(F.ahead)} service unpaid</span>`);
 if(r.med==="Not recorded")o.push(`<span class="flg n">⚕️ Medical status not recorded</span>`);
 else if(r.med!=="Fit")o.push(`<span class="flg r big">⚕️ ${r.medAll} — consultant review</span>`);
 else o.push(`<span class="flg g">✅ Medically fit</span>`);
 if(r.cmpOpen)o.push(`<span class="flg r big">⚠️ ${r.cmp} open concern${r.cmp>1?"s":""} · ${r.cmpt}</span>`);
 else if(r.cmp)o.push(`<span class="flg n">✔ ${r.cmp} concern closed</span>`);
 if(r.zs)o.push(`<span class="flg r big">⭕ ZERO SESSION</span>`);
 if(r.status!=="Active")o.push(`<span class="flg ${r.status==="Deactivated"?"r":"a"}">${r.status==="Deactivated"?"⛔ Deactivated":"⏸ On break"}</span>`);
 if(r.reg==="Irregular")o.push(`<span class="flg a">📉 Irregular · ${r.amv}/mo</span>`);
 if(r.ct==="DND")o.push(`<span class="flg r big">📵 DND — do not contact</span>`);
 o.push(r.card?`<span class="flg b">💳 Card ${r.card}</span>`:`<span class="flg a">💳 Card not issued</span>`);
 if(!r.pdok)o.push(`<span class="flg a">📄 PD form pending</span>`);
 if(gapD(r.last)>60&&r.vis>0)o.push(`<span class="flg a">🚶 No visit ${gapD(r.last)}d</span>`);
 if(!r.lastFU)o.push(`<span class="flg a">📞 No followup recorded</span>`);
 if(gapD(r.lastFU)>30)o.push(`<span class="flg a">📞 No followup ${gapD(r.lastFU)}d</span>`);
 return o.join("");
}

