async function load360(r){
 const id=r.id;
 const [fu,ss]=await Promise.all([
  r.actsLoaded?null:safe(gl("Client Followup",[["client","=",r.pid]],["name","followup_date","followup_type","status","remarks","call_outcome","owner"],{order:"followup_date desc",limit:40}),[],"Followups"),
  safe(gl("Therapy Session",[["therapy_plan","=",r.plan],["docstatus","=",1]],["name","start_date","custom_actual_session_date","therapy_type","custom_practitioner_name","practitioner","before_weight","after_weight","custom_inch_loss"],{order:"start_date asc",limit:1000}),[],"Session log")
 ]);
 if(fu){
  r.acts=fu.map(f=>({ic:/complain|concern|grievance/i.test(f.followup_type||"")?"😟":"🔁",t:"Followup — "+(cln(f.followup_type)||"call"),
   note:cln(f.remarks||f.call_outcome||f.status||"logged"),by:cln(String(f.owner||"").split("@")[0])||"—",d:iso10(f.followup_date)})).filter(x=>x.d);
  r.actsLoaded=true;
 }
 const m=document.getElementById("mod");
 if(!m||m.dataset.id!==id||!document.getElementById("ov").classList.contains("on"))return;
 const a=document.getElementById("acts360");if(a)a.innerHTML=actsBlock(r);
 const s=document.getElementById("ses360");if(!s)return;
 s.innerHTML=ss.length?`<table class="ftab"><thead><tr><th>#</th><th>Session date</th><th>Therapy</th><th>Executed by</th>${r.isSlim?"<th>Before</th><th>After</th><th>Change</th><th>Inch loss</th>":""}</tr></thead><tbody>${ss.map((x,i)=>{
   const bw=N(x.before_weight),aw=N(x.after_weight),dl=bw&&aw?Math.round((bw-aw)*10)/10:null;
   return `<tr><td>${i+1}</td><td>${fdt(x.custom_actual_session_date||x.start_date)}</td><td>${cln(x.therapy_type)||"—"}</td><td>${cln(x.custom_practitioner_name)||LIVE.prac[x.practitioner]||cln(x.practitioner)||"—"}</td>${r.isSlim?`<td>${bw?bw+" kg":"—"}</td><td>${aw?aw+" kg":"—"}</td><td class="${dl>0?"g":dl<0?"r":""}">${dl==null?"—":(dl>0?"−":dl<0?"+":"")+Math.abs(dl)+" kg"}</td><td>${N(x.custom_inch_loss)?N(x.custom_inch_loss)+" in":"—"}</td>`:""}</tr>`}).join("")}</tbody></table>`
  :`<div class="falert cr">No submitted session yet on this enrollment.</div>`;
}

