 const L=[H.map(q).join(",")];
 rows.forEach((r,i)=>{const F=fin(r);L.push([i+1,r.pid,r.name,r.mob,r.alt,r.gen,isNaN(r.age)?"":r.age,r.br+" "+r.brn,r.bm,r.cl,r.jby,r.rby,r.pkg,r.disc,r.dpc,r.net,r.paid,r.due,r.pay,r.enrolled,r.start,r.medAll,r.cons,r.cc,r.pd,r.pdok?"Received":"Pending",tierOf(r)||"Standard",r.cat,r.main,r.grps.join(" + "),r.plans.join(" + "),r.lines.map(l=>l.part).join(" + "),r.sesB,r.sesC,r.sesB-r.sesC,r.apt,r.vis,Math.max(0,r.apt-r.vis),r.inv,r.invNo,r.rebook,r.card,r.email,r.crE,r.crU,r.cmp,r.cmpOpen?"Open":(r.cmp?"Closed":"—"),r.amv,r.ct,r.zs?"YES":"No",r.pct,r.status,r.reg,r.last,r.lastFU,r.nextDue||"",r.due,F.perS,F.used,F.unused,F.paidSess,F.colPct,r.plan,r.wJ||"",r.wP||"",r.wl==null?"":r.wl,r.il||"",r.src,r.nj?"NJ":""].map(q).join(","))});
 const b=new Blob(["\ufeff"+L.join("\r\n")],{type:"text/csv;charset=utf-8"}),a=document.createElement("a");
 a.href=URL.createObjectURL(b);a.download="LIFE_Enrollment_Register_"+TODAY+".csv";document.body.appendChild(a);a.click();a.remove();
 setTimeout(()=>URL.revokeObjectURL(a.href),1500);
 toast(rows.length+" records exported");
}
