/* ═══════════ CAPACITY PLANNER ═══════════ */
const CAPS={};
function initCap(){document.getElementById("c_br").innerHTML=BR.map(b=>`<option value="${b.c}">${b.c} · ${b.n}</option>`).join("")}
function resetCap(){
 const V={c_open:"09:00",c_close:"20:00",c_rooms:6,c_mach:5,c_staff:7,c_dur:45,c_chg:10,c_brk:60,c_mpc:60,c_util:85,c_days:26};
 Object.keys(V).forEach(k=>document.getElementById(k).value=V[k]);
 calcCap();
}
function calcCap(){
 const g=id=>document.getElementById(id), n=id=>+g(id).value;
 const br=g("c_br").value, b=BR.find(x=>x.c===br);
 const [oh,om]=g("c_open").value.split(":").map(Number), [ch,cm]=g("c_close").value.split(":").map(Number);
 let mins=(ch*60+cm)-(oh*60+om); if(mins<=0)mins+=1440;
 const slot=n("c_dur")+n("c_chg"), util=n("c_util")/100;
 const rooms=n("c_rooms"), mach=n("c_mach"), staff=n("c_staff"), mpc=n("c_mpc")/100;
 const slotsPer=Math.floor(mins/slot);
 const staffMins=Math.max(0,mins-n("c_brk")), staffSlots=Math.floor(staffMins/slot);
 const capRoom=rooms*slotsPer, capStaff=staff*staffSlots;
 const capMach=mpc>0?Math.floor(mach*slotsPer/mpc):Infinity;
 const raw=Math.min(capRoom,capStaff,capMach);
 const day=Math.floor(raw*util);
 const names={room:"Rooms / beds",staff:"Therapists / technicians",mach:"Machines"};
 const bn=raw===capRoom?"room":(raw===capStaff?"staff":"mach");
 const cap={room:capRoom,staff:capStaff,mach:capMach===Infinity?"—":capMach};
 // demand from register
 const live=DATA.filter(r=>r.br===br&&r.status==="Active");
 const demand=Math.round(live.reduce((s,r)=>s+r.amv,0)/n("c_days")*1);
 const pend=live.reduce((s,r)=>s+(r.sesB-r.sesC),0);
 const load=day?Math.round(demand/day*100):0;
 const cls=load>100?"r":load>85?"a":load>50?"g":"b";
 const bcls=load>100?"cr":load>85?"wr":"ok";
 CAPS[br]={br:br,name:b.n,mins:mins,slot:slot,day:day,month:day*n("c_days"),demand:demand,load:load,bn:names[bn],rooms:rooms,mach:mach,staff:staff,pend:pend};
 const cc=(c,k,v,d)=>`<div class="cc ${c}"><div class="k">${k}</div><div class="v">${v}</div><div class="d">${d}</div></div>`;
 const hours=Math.floor(mins/60)+"h "+(mins%60)+"m";
 let rowsT=Object.values(CAPS).map(c=>`<tr><td>${c.br} · ${c.name}</td><td>${c.rooms}</td><td>${c.mach}</td><td>${c.staff}</td><td>${Math.floor(c.mins/60)}h</td><td>${c.slot}m</td><td>${c.day}</td><td>${c.day*7}</td><td>${c.month}</td><td>${c.demand}</td><td class="${c.load>100?"bd":c.load>85?"":"gd"}">${c.load}%</td><td>${c.bn}</td><td>${c.pend}</td></tr>`).join("");
 document.getElementById("capout").innerHTML=`
 <div class="bneck ${bcls}">Bottleneck: <b>${names[bn]}</b> — this is what caps ${b.c} ${b.n} at <b>${day} sessions a day</b>.
  ${load>100?"Demand is above capacity; add "+names[bn].toLowerCase()+" or extend hours.":load>85?"Running close to the ceiling — little room for walk-ins or reschedules.":"Capacity is comfortable against current demand."}</div>
 <div class="capcards">
  ${cc("g","Sessions per day",day,`${hours} open · ${slot} min per slot incl. changeover`)}
  ${cc("b","Per week / month",day*7+" / "+day*n("c_days"),`${n("c_days")} working days a month`)}
  ${cc(cls,"Current demand / day",demand,`${load}% of capacity · ${live.length} active clients`)}
  ${cc(load>100?"r":"p","Spare capacity / day",Math.max(0,day-demand),`${pend} sessions pending in the branch`)}
  ${cc("a","Slots per station",slotsPer,`staff get ${staffSlots} after ${n("c_brk")} min break`)}
 </div>
 <table class="anz">
  <tr><th>Resource</th><th>Available</th><th>Slots each</th><th>Sessions possible</th><th>Status</th></tr>
  <tr><td>Rooms / beds</td><td>${rooms}</td><td>${slotsPer}</td><td>${capRoom}</td><td class="${bn==="room"?"bd":"gd"}">${bn==="room"?"BOTTLENECK":"sufficient"}</td></tr>
  <tr><td>Machines (${n("c_mpc")}% of sessions)</td><td>${mach}</td><td>${slotsPer}</td><td>${cap.mach}</td><td class="${bn==="mach"?"bd":"gd"}">${bn==="mach"?"BOTTLENECK":"sufficient"}</td></tr>
  <tr><td>Therapists / technicians</td><td>${staff}</td><td>${staffSlots}</td><td>${capStaff}</td><td class="${bn==="staff"?"bd":"gd"}">${bn==="staff"?"BOTTLENECK":"sufficient"}</td></tr>
  <tr class="tot"><td>Practical capacity @ ${n("c_util")}% utilisation</td><td>—</td><td>—</td><td>${day}</td><td>${load}% loaded</td></tr>
 </table>
 <div class="repnote" style="margin-top:8px">Branches configured in this session — add more by choosing another branch and calculating again.</div>
 <table class="anz">
  <tr><th>Branch</th><th>Rooms</th><th>Mach</th><th>Staff</th><th>Open</th><th>Slot</th><th>Per day</th><th>Per week</th><th>Per month</th><th>Demand/day</th><th>Load</th><th>Bottleneck</th><th>Pending sess</th></tr>
  ${rowsT}</table>`;
}
function printCap(){
 const c=CAPS[document.getElementById("c_br").value];
 if(!c){calcCap()}
 printDoc(`<div class="rp"><h2>Session capacity plan</h2><div class="sub">Capacity against current register demand.</div>
  ${document.getElementById("capout").querySelectorAll("table")[1].outerHTML}</div>`,"landscape");
}

