  s60:a.filter(r=>D60(r)>60).length,s30:a.filter(r=>D60(r)<=30).length,
  med:a.filter(r=>r.med!=="Fit").length,
  hold:a.filter(r=>["Pregnancy Hold","Under Review","Post Surgery"].includes(r.med)).length,
  hi:a.filter(HI).length,
  od:a.filter(OVD).length,
  cmp:a.filter(r=>r.cmp).length,opn:a.filter(r=>r.cmpOpen).length,
  ref:a.reduce((s,r)=>s+r.refG,0),dnd:a.filter(r=>r.ct==="DND").length,
