  nval:a.reduce((s,r)=>s+r.net,0),paidv:a.reduce((s,r)=>s+r.paid,0),duev:a.reduce((s,r)=>s+r.due,0),
  usedv:a.reduce((s,r)=>s+r.lines.reduce((t,l)=>t+l.used,0),0),
  odv:a.filter(OVD).reduce((s,r)=>s+r.due,0),
  pl:a.reduce((s,r)=>s+r.plans.length,0),
  ns:a.filter(r=>r.pct===0).length,
  st:a.filter(r=>r.pct>0).length,
  ip:a.filter(r=>r.pct>0&&r.pct<100).length,
  p25:a.filter(r=>r.pct>0&&r.pct<=25).length,
  p50:a.filter(r=>r.pct>25&&r.pct<=50).length,
  p75:a.filter(r=>r.pct>50&&r.pct<=75).length,
  p99:a.filter(r=>r.pct>75&&r.pct<100).length,
  ci:a.filter(r=>r.status==="Deactivated"&&r.pct<100).length,
  drp:a.filter(r=>r.status!=="Active"&&r.pct<100).length,
  days:a.length?Math.round(a.reduce((s,r)=>s+(new Date(TODAY)-new Date(r.start))/864e5,0)/a.length):0,
  cdays:(()=>{const c=a.filter(r=>r.pct===100);return c.length?Math.round(c.reduce((s,r)=>s+(new Date(r.last||r.start)-new Date(r.start))/864e5,0)/c.length):0})()};
