};
function build(rows,label,segs,keys){
 const cols=keys.map(k=>C[k]);
 const head=[label].concat(cols.map(c=>c[0]));
 const body=segs.map(s=>{const a=rows.filter(s.f);return [s.l].concat(cols.map(c=>c[1](met(a),a)))})
                .filter(r=>r[1]!==0&&r[1]!=="0");
 const tot=["TOTAL"].concat(cols.map(c=>c[1](met(rows),rows)));
 return {head,body,tot};
}
function build2(rows,groups,keys){
 const cols=keys.map(k=>C[k]);
 const head=["Group","Segment","Clients","Share"].concat(cols.map(c=>c[0]));
 const N=rows.length||1, body=[];
 groups.forEach(g=>{
  g.segs.forEach((s,i)=>{
   const a=rows.filter(s.f); if(!a.length)return;
   body.push([i===0?g.g:"",s.l,a.length,Math.round(a.length/N*100)+"%"].concat(cols.map(c=>c[1](met(a),a))));
  });
 });
 const m=met(rows);
 const tot=["","ALL RECORDS",rows.length,"100%"].concat(cols.map(c=>c[1](m,rows)));
 return {head,body,tot};
}
