const POL={};
"Clients|New|Rebook #|Rebooks|Female|Male|Plans|Active|Regular|Sess bkd|Sess done|Visits|Visit/client|AMV|Avg %|100% done|Completed|Started|Completion %|Visited 30d|FU done 30d|VIP+|HNI|Referrals|Value ₹L|Invoices|Packages|In progress|Start %|Session use %|Started|Joined|Total".split("|").forEach(k=>POL[k]=1);
"Break|Deactiv|Irregular|Zero sess|Zero %|Sess bal|No visit 60d+|FU pending|Medical flag|Med hold|Concerns|Open|Overdue|High risk|Risk %|DND|Not started|Closed incomplete|Dropped|Avg days to close|Avg days open".split("|").forEach(k=>POL[k]=-1);
function pnum(v){
 if(typeof v==="number")return v;
 const s=String(v);
 if(s.indexOf(":")>-1||s==="·"||s==="—"||s==="")return null;
 const m=s.replace(/[₹,%L\s]/g,"");
 const f=parseFloat(m); return isNaN(f)?null:f;
}
function tbl(d,sel){
 const K=i=>!sel||sel[i];
 const pol=d.head.map(t=>POL[t]||(/✓$/.test(t)?1:0));
 const avg=d.head.map((t,i)=>{
  if(!pol[i])return null;
  const vs=d.body.map(r=>pnum(r[i])).filter(x=>x!==null);
  return vs.length?vs.reduce((a,b)=>a+b,0)/vs.length:null;
 });
 const cls=(v,i)=>{
  if(!pol[i]||avg[i]===null)return "";
  const x=pnum(v); if(x===null)return "";
  if(x===0&&pol[i]===-1)return "gd";
  const hi=avg[i]*1.15, lo=avg[i]*0.85;
  if(pol[i]===1)return x>=hi?"gd":(x<=lo?"bd":"");
  return x<=lo?"gd":(x>=hi?"bd":"");
 };
 return `<table class="anz"><tr>${d.head.map((x,i)=>K(i)?`<th>${x}</th>`:"").join("")}</tr>
  ${d.body.map(r=>{const sp=/^TOP 25|^— all|^ALL /.test(String(r[0]));
    return `<tr class="${sp?"sp":""}">${r.map((c,i)=>K(i)?`<td class="${sp?"":cls(c,i)}">${c}</td>`:"").join("")}</tr>`}).join("")}
  <tr class="tot">${d.tot.map((c,i)=>K(i)?`<td>${c}</td>`:"").join("")}</tr></table>`;
}
