const TZ=document.getElementById("tzone"), TS=document.getElementById("tscroll");
function arrows(){
 const max=TS.scrollWidth-TS.clientWidth;
 TZ.classList.toggle("hint-l",TS.scrollLeft>4);
 TZ.classList.toggle("hint-r",TS.scrollLeft<max-4);
 const hid=Math.max(0,Math.round(max/110));
 document.getElementById("hidnote").textContent = max>4
   ? "≈ "+hid+" more column"+(hid===1?"":"s")+" hidden — move the mouse to the edge, drag the grid, or use ← →"
   : "";
}
function nudge(d){TS.scrollBy({left:d*340,behavior:"smooth"})}

/* Manual horizontal movement only.
   Hovering the table or the arrow buttons must never move the table. */
function glide(d){ /* intentionally disabled */ }

function scrollEdge(e){TS.scrollTo({left:e?TS.scrollWidth:0,behavior:"smooth"})}

/* Auto edge-hover scrolling removed.
   Users can still:
   - click ◀ / ▶ to move one step
   - click ⇤ / ⇥ to go to first/last column
   - drag the table horizontally
   - use the normal horizontal scrollbar */

let dgX=null,dgL=0;
